globalThis.MAMBEU_TOURS=[{"id":574,"slug":"7-days-tanzania-royal-safari","title":"7 Days Tanzania Royal Safari","description":"Immerse yourself in an active tour adventure in Tanzania, where you'll trade the Jeep for walking boots and embrace the thrill of hiking through the","fullDescription":"Immerse yourself in an active tour adventure in Tanzania, where you'll trade the Jeep for walking boots and embrace the thrill of hiking through the wilderness. This 7-day royal safari takes you through Tanzania's most iconic national parks.","image":"/assets/hero.webp","mapImage":"","duration":"7 Days","airport":"","category":"northern-safari","pricingTiers":[],"itinerary":[],"highlights":["Serengeti National Park","Ngorongoro Crater","Tarangire National Park"],"included":[],"excluded":[],"gallery":[],"featured":false,"createdAt":"2026-07-16T18:33:55.350Z","updatedAt":"2026-07-16T18:33:55.350Z","path":"journey-574","style":"Comfort","days":7},{"id":576,"slug":"3-days-tanzania-budget-safari","title":"3 Days Tanzania Budget Safari","description":"Discover Northern Tanzania with Mambeu Safaris: Your Perfect Short Camping Safari. If you have just a few days to explore northern Tanzania, our tailored camping","fullDescription":"Discover Northern Tanzania with Mambeu Safaris: Your Perfect Short Camping Safari. If you have just a few days to explore northern Tanzania, our tailored camping safari is perfect for you.","image":"/assets/hero.webp","mapImage":"","duration":"3 Days","airport":"","category":"northern-safari","pricingTiers":[],"itinerary":[],"highlights":["Budget-Friendly","Camping Experience","Tarangire & Ngorongoro"],"included":[],"excluded":[],"gallery":[],"featured":false,"createdAt":"2026-07-16T18:33:55.350Z","updatedAt":"2026-07-16T18:33:55.350Z","path":"journey-576","style":"Camping","days":3},{"id":302,"slug":"5-Day Tanzania Highlights Wildlife Safari","title":"5-Day Tanzania Highlights Wildlife Safari","description":"Experience the finest of northern Tanzania’s legendary parks on a journey crafted for discerning travelers.","fullDescription":"Experience the finest of northern Tanzania’s legendary parks on a journey crafted for discerning travelers. From elephant-rich plains and dramatic crater rims to the endless savannahs of the Serengeti, this safari offers close-up wildlife encounters paired with handpicked, luxurious accommodations that ensure comfort, exclusivity, and an unforgettable connection to the wild.","image":"/assets/tour-302.webp","mapImage":"https://mambeu.safezonetz.com/uploads/1767968436700-586988525.jpg","duration":"5 Days / 4 Nights","airport":"Kilimanjaro International Airport (JRO)","category":"Classic Safari","pricingTiers":[{"people":"1 person","price":3566},{"people":"2 people","price":2646},{"people":"3 people","price":2335},{"people":"4 people","price":2247},{"people":"5 people","price":2116},{"people":"6 people","price":2074}],"itinerary":[{"day":1,"title":"Tarangire National Park – Majestic Elephants & Baobabs","description":"Arrive in Arusha and continue to Tarangire National Park, renowned for its towering baobab trees and impressive elephant herds.\nTarangire is famed for its diverse landscapes and nine distinct vegetation zones, but its true icons are the ancient baobab trees—towering giants that dwarf the wildlife around them—and its abundant elephant herds, the largest concentration in the country. The park’s Tarangire River attracts an incredible variety of wildlife, including lions, leopards, zebras, giraffes, buffaloes, antelopes, and numerous bird species.\n\nEnjoy an afternoon private game drive customized to your interests, offering excellent opportunities for wildlife viewing and photography as you explore the park’s diverse habitats.\n\nEnd the day with sunset cocktails set against Tarangire’s serene landscape, soaking in the warm hues of the African sky as the wilderness comes alive around you.","image":"https://mambeu.safezonetz.com/uploads/1767968741653-872765970.jpg","accommodation":"Tarangire Safari Lodge","meals":"Lunch & dinner (Breakfast not included) All drinks (Except for spirits/liquor)"},{"day":2,"title":"Lake Manyara National Park – Lakeside Wildlife & Birding","description":"Depart from the lodge to Lake Manyara, a park celebrated for its colorful flamingos, legendary tree-climbing lions, and remarkable diversity of bird species.\n\nBegin your day with private game drives along the lakeshore, exploring lush forests, open plains, and the vibrant wetlands teeming with wildlife. In the afternoon, continue your adventure with optional guided nature walks or a photography-focused safari, capturing the magical golden light over the water.\n\nAs evening approaches, unwind at your lodge, enjoying peaceful lake views and the tranquil atmosphere that surrounds this beautiful setting.","image":"https://mambeu.safezonetz.com/uploads/1767968829243-834066345.jpg","accommodation":"Bougainvillea Safari Lodge","meals":"Lunch & dinner (Breakfast not included) All drinks (Except for spirits/liquor)"},{"day":3,"title":"Ngorongoro Crater - Africa's Natural Amphitheater","description":"Ascend to the breathtaking Ngorongoro Crater, one of the world’s most extraordinary wildlife sanctuaries and a true natural wonder.\n\nDescend onto the crater floor for an exclusive private game drive, where you’ll encounter endangered rhinos, powerful lions, grazing zebras, and flocks of elegant flamingos set against dramatic volcanic scenery.\n\nSavor a gourmet bush lunch overlooking the vast crater, surrounded by sweeping panoramic views and the sounds of the wilderness.\n\nIn the evening, retreat to your accommodation in Serengeti National Park, perfect for stargazing beneath crystal-clear skies or enjoying a romantic private dinner in the bush.","image":"https://mambeu.safezonetz.com/uploads/1767968934787-969567650.jpg","accommodation":"Serengeti Kati Kati Tented Camp","meals":"All meals included All drinks (Except for spirits/liquor)"},{"day":4,"title":"Serengeti National Park – Endless Plains & Wildlife","description":"Journey onward to the legendary Serengeti, Tanzania’s most iconic wildlife sanctuary and home to some of the greatest concentrations of animals on Earth.\n\nIn the afternoon, enjoy a private game drive through the Central Serengeti, where you’ll have the chance to observe lions lounging in the grasslands, elephants moving gracefully across the plains, and vast herds of zebras and wildebeest grazing in their natural habitat.\n\nFor a perfect end to the day, opt for a scenic sundowner atop a rocky kopje, offering sweeping panoramic views and exceptional opportunities for golden-hour photography.","image":"https://mambeu.safezonetz.com/uploads/1767969052554-623317086.jpg","accommodation":"Serengeti Kati Kati Tented Camp","meals":"All meals included All drinks (Except for spirits/liquor)"},{"day":5,"title":"Serengeti & Return to Arusha – Farewell to the Wild","description":"Begin your day with a final morning game drive in the Serengeti, taking in one last opportunity to witness Africa’s iconic wildlife in their natural habitat—whether it’s lions on the hunt, elephants moving across the plains, or herds of antelope grazing in the early light.\n\nBy midday, start your journey back to Arusha, enjoying the ever-changing scenery as you leave the vast savannahs behind. An optional lunch stop along the way allows you to relax and reflect on the unforgettable experiences of your safari.\n\nUpon arrival in Arusha, continue with your onward travel plans or prepare for departure, bringing your remarkable adventure to a close.","image":"","accommodation":"No accommodation (End of tour)","meals":"Breakfast & lunch (Dinner not included) All drinks (Except for spirits/liquor)"}],"highlights":[],"included":[],"excluded":[],"gallery":[],"featured":true,"createdAt":"2026-01-09T14:33:21.340Z","updatedAt":"2026-01-09T14:34:05.353Z","path":"journey-302","style":"Comfort","days":5},{"id":301,"slug":"4-Day Wilderness Luxury Safari","title":"4-Day Wilderness Luxury Safari","description":"Experience Tanzania’s top wildlife destinations with a safari through the Serengeti, Ngorongoro Crater, and seasonally Tarangire or Lake Manyara.","fullDescription":"Experience Tanzania’s top wildlife destinations with a safari through the Serengeti, Ngorongoro Crater, and seasonally Tarangire or Lake Manyara. See tree-climbing lions, flamingos, elephants, and baobabs as each park offers unique wildlife encounters and rich birdlife. With Mambeu Safaris’ expert guides and well-crafted itineraries, enjoy an unforgettable journey through Tanzania’s iconic landscapes and vibrant wildlife.","image":"/assets/tour-301.webp","mapImage":"https://mambeu.safezonetz.com/uploads/1767967292226-528441569.jpg","duration":"3 Nights / 4 Days","airport":"Kilimanjaro International Airport (JRO)","category":"Classic Safari","pricingTiers":[{"people":"1 person","price":4675},{"people":"2 people","price":3329},{"people":"3 people","price":3168},{"people":"4 people","price":2970},{"people":"5 people","price":2947},{"people":"6 people","price":2853}],"itinerary":[{"day":1,"title":"Arusha – Lake Manyara National Park","description":"After a short briefing in the morning, you set off to the Lake Manyara National Park. The small park stretches along the 600 m high Rift Valley Escarpment and is dominated by the alkaline Lake Manyara. It is here where thousands of flamingos seem to colour the shallow waters pink. Many water birds gather at the lake and more than 400 bird species are found in the park.\n\nThe diverse vegetation provides a habitat for many animals such as monkeys in the forest, giraffes and antelopes on the grasslands and elephants around the acacia trees. If you are very lucky you might also see the Manyara lions, lounging in the trees. In the late afternoon you will leave the Lake Manyara National Park and head to the Neptune Ngorongoro Luxury Lodge, where you will spend the night.","image":"https://mambeu.safezonetz.com/uploads/1767967640623-293096736.jpeg","accommodation":"Neptune Ngorongoro Luxury Lodge","meals":"Lunch & dinner (Breakfast not included) All drinks (Except for spirits/liquor)"},{"day":2,"title":"Lake Manyara – Serengeti National Park","description":"After breakfast, drive through the fertile crater highlands, where the Iraqw people cultivate wheat, corn, and coffee. Passing the Ngorongoro Crater, continue toward the vast Serengeti plains, arriving around midday.\n\nSerengeti National Park is one of Africa’s most iconic wildlife destinations, renowned for its endless plains and rich diversity of animals. Large herds of wildebeest, buffalo, elephants, giraffes, eland, impalas, and gazelles roam the landscape, while predators such as lions and leopards are frequently spotted. The park features varied habitats, including open plains, savannah, bush, swamps, kopjes, and seasonal lakes. Depending on the time of year, you may witness the great wildebeest migration.\n\nEnjoy a game drive through this remarkable ecosystem, stopping for a scenic picnic lunch before continuing your exploration.\n\nAs the day ends, return to your lodge for dinner and an overnight stay.","image":"https://mambeu.safezonetz.com/uploads/1767967844613-624785939.jpeg","accommodation":"Serengeti Serena Safari Lodge","meals":"All meals included All drinks (Except for spirits/liquor)"},{"day":3,"title":"Serengeti – Ngorongoro Crater","description":"Dawn is a good time to watch wildlife and so you will be up early to join an early morning game drive. You will return to the camp for breakfast before heading out for another game drive in the park. Here in the Seronera region you will often see wildebeests and zebras in close proximity of lions and other predators such as leopards and cheetahs. After a picnic lunch you will continue your journey towards the Ngorongoro Crater. Once you have reached the crater rim you will enjoy fantastic views of this 600 m deep collapsed volcano. You will stay at the Ngorongoro Lion’s Paw Camp, situated on the crater rim.","image":"https://mambeu.safezonetz.com/uploads/1767967969845-894453309.jpg","accommodation":"Ngorongoro Lion's Paw Camp","meals":"All meals included All drinks (Except for spirits/liquor)"},{"day":4,"title":"Ngorongoro Crater – Arusha/Airport","description":"After an early breakfast you will drive down the steep and narrow road that takes you into the crater. The slopes are forested but soon the landscape changes to savannah. Here the wildlife is just breath-taking and with a little luck you can observe the Big Five – lion, elephant, buffalo, rhino and leopard – in just a few hours. You should also see warthogs, wildebeests, zebras, hippos and some of the more than 500 bird species of the area. After a morning dedicated to game viewing and a picnic lunch, you will leave the crater in the early afternoon to drive back to Arusha, where you will arrive in the early evening.","image":"","accommodation":"No accommodation (End of tour)","meals":"Breakfast & lunch (Dinner not included) All drinks (Except for spirits/liquor)"}],"highlights":[],"included":["Park fees","(For non-residents)","All activities","(Unless labeled as optional)","All accommodation","(Unless listed as upgrade)","A professional driver/guide","All transportation","(Unless labeled as optional)","All Taxes/VAT","Roundtrip airport transfer","Meals","(As specified in the day-by-day section)","Drinks","(As specified in the day-by-day section)"],"excluded":["International flights","(From/to home)","Additional accommodation before and at the end of the tour","Tips","(Tipping guideline US$10.00 pp per day)","Personal items","(Souvenirs, travel insurance, visa fees, etc.)","Government imposed increase of taxes and/or park fees"],"gallery":[],"featured":true,"createdAt":"2026-01-09T14:15:03.007Z","updatedAt":"2026-01-09T14:15:03.007Z","path":"journey-301","style":"Luxury","days":4},{"id":300,"slug":"6-Day All Inclusive Luxury Safari","title":"6-Day All Inclusive Luxury Safari","description":"This safari takes you through the country’s most iconic parks, Tarangire, Serengeti, & Ngorongoro Crater.","fullDescription":"This safari takes you through the country’s most iconic parks, Tarangire, Serengeti, & Ngorongoro Crater. Enjoy close encounters with elephants, lions, and countless other wildlife as you travel across breathtaking landscapes. With comfortable lodges and expert guides, this adventure offers the perfect mix of excitement, beauty, and relaxation in the heart of Africa.","image":"/assets/tour-300.webp","mapImage":"https://mambeu.safezonetz.com/uploads/1767962403615-756922607.jpg","duration":"6 Days / 5 Night","airport":"","category":"","pricingTiers":[{"people":"1 person","price":5381},{"people":"2 people","price":3550},{"people":"3 people","price":3156},{"people":"4 people","price":3022},{"people":"5 people","price":2914},{"people":"6 people","price":2841}],"itinerary":[{"day":1,"title":"Arrival in Arusha","description":"Settle into Arusha, a friendly city surrounded by beautiful scenery and the towering peak of Mount Meru. It’s the perfect spot to relax before your safari & stroll through bustling markets, try some local Tanzanian food, and enjoy the peaceful views as you get ready for the adventures that lie ahead in the wild.","image":"https://mambeu.safezonetz.com/uploads/1767962714354-347486791.jpg","accommodation":"Gran Meliá Arusha","meals":"Dinner (Breakfast & lunch not included) Drinking water (Other drinks not included)"},{"day":2,"title":"Tarangire National Park","description":"Spend the day discovering the magic of Tarangire National Park, a quiet and beautiful place filled with towering baobab trees and herds of gentle elephants. As you wander through its golden plains, you’ll see zebras grazing, giraffes moving gracefully between the trees, and if you’re lucky, lions resting in the shade. The peaceful atmosphere and stunning landscapes make Tarangire a truly unforgettable part of your safari adventure.","image":"https://mambeu.safezonetz.com/uploads/1767962948339-539804348.jpg","accommodation":"Lake Burunge Baobab Tented Lodge","meals":"All meals included Drinking water (Other drinks not included)"},{"day":3,"title":"Tarangire to Central Serengeti NP","description":"After breakfast, say goodbye to Tarangire and begin your journey to the Central Serengeti. The drive is full of beautiful scenery & quiet villages, open plains, and the chance to spot wildlife along the way. As you reach the Serengeti, the vast grasslands stretch endlessly before you, setting the stage for an exciting adventure in one of Africa’s most famous safari destinations.","image":"https://mambeu.safezonetz.com/uploads/1767963152419-655514772.jpeg","accommodation":"Kubu Kubu Tented Lodge","meals":"All meals included Drinking water (Other drinks not included)"},{"day":4,"title":"Central Serengeti NP","description":"Spend a full day exploring the endless plains of the Central Serengeti, where wildlife roams freely across the golden savannah. Enjoy game drives at your own pace, watching lions bask in the sun, elephants wandering in herds, and cheetahs sprinting across the open plains. With every turn, the Serengeti reveals something new, making each moment an unforgettable part of your safari adventure.","image":"https://mambeu.safezonetz.com/uploads/1767963275822-986251809.jpg","accommodation":"Kubu Kubu Tented Lodge","meals":"All meals included Drinking water (Other drinks not included)"},{"day":5,"title":"Central Serengeti NP to Ngorongoro Crater","description":"Leave the Central Serengeti and travel towards Ngorongoro. Descend into the crater for wildlife viewing among grasslands, lakes and volcanic scenery. Continue to Kitela Lodge for the night.","image":"https://mambeu.safezonetz.com/uploads/1767963456250-22313281.jpeg","accommodation":"Kitela Lodge","meals":""},{"day":6,"title":"Ngorongoro Crater to Arusha","description":"As your safari comes to an end, enjoy a scenic drive back to Arusha. Along the way, take in the final views of Tanzania’s beautiful landscapes. Depending on your schedule, you can stop by local markets to shop for souvenirs and handmade crafts before continuing to your hotel or the airport for your onward journey or ending your adventure with lasting memories of Africa’s wild beauty.","image":"","accommodation":"No accommodation (End of tour)","meals":"Breakfast & lunch (Dinner not included) Drinking water (Other drinks not included)"}],"highlights":[],"included":["Park fees","(For non-residents)","All activities","(Unless labeled as optional)","All accommodation","(Unless listed as upgrade)","A professional driver/guide","All transportation","(Unless labeled as optional)","All Taxes/VAT","Roundtrip airport transfer","Meals","(As specified in the day-by-day section)","Drinking water","(On all days)"],"excluded":["International flights","(From/to home)","Additional accommodation before and at the end of the tour","Tips","(Tipping guideline US$10.00 pp per day)","Personal items","(Souvenirs, travel insurance, visa fees, etc.)","Government imposed increase of taxes and/or park fees","Some meals","(As specified in the day-by-day section)"],"gallery":[],"featured":true,"createdAt":"2026-01-09T13:02:41.528Z","updatedAt":"2026-01-21T14:45:08.870Z","path":"journey-300","style":"Luxury","days":6},{"id":299,"slug":"4-Day Short Luxury Safari Adventure","title":"4-Day Short Luxury Safari Adventure","description":"This 4-day Tanzania safari begins with a relaxing night in Arusha before exploring Lake Manyara National park, Tarangire National park, and the Ngorongoro Crater.","fullDescription":"This 4-day Tanzania safari begins with a relaxing night in Arusha before exploring Lake Manyara National park, Tarangire National park, and the Ngorongoro Crater. Enjoy game drives among elephants, lions, and flamingos while taking in the stunning scenery of northern Tanzania. A short yet unforgettable journey through some of Africa’s most iconic landscapes.","image":"/assets/tour-299.webp","mapImage":"https://mambeu.safezonetz.com/uploads/1767961276114-117029720.jpg","duration":"4 Days / 3 Nights","airport":"","category":"Classic Safari","pricingTiers":[{"people":"1 person","price":3109},{"people":"2 people","price":1912},{"people":"3 people","price":1631},{"people":"4 people","price":1469},{"people":"5 people","price":1410},{"people":"6 people","price":1354}],"itinerary":[{"day":1,"title":"Arrival in Arusha","description":"On arrival at Kilimanjaro International Airport, you’ll receive a warm welcome and be transferred to Arusha. After a short briefing, sharing fascinating stories and learn about the local people and their rich culture —offering a captivating introduction to Tanzanian life before your adventure into the wilderness unfolds.\n\nSpend a relaxing night in Arusha, a lively city surrounded by beautiful landscapes and views of Mount Meru. It’s the perfect place to unwind, explore local cultures, and get ready for your safari adventure across Tanzania’s incredible national parks.\n\nEnjoy dinner and an overnight stay at your Arusha accommodation, where you can relax and recharge in comfort.","image":"https://mambeu.safezonetz.com/uploads/1767961460267-637520886.jpg","accommodation":"Kahawa House","meals":"Dinner (Breakfast & lunch not included) Non-alcoholic drinks"},{"day":2,"title":"Lake Manyara National Park","description":"Leaving Arusha, enjoy a beautiful drive through small villages and green highlands on your way to Lake Manyara National Park. The journey offers a glimpse of local life and stunning views before you arrive at the park, known for its elephants, hippos, and tree-climbing lions.","image":"https://mambeu.safezonetz.com/uploads/1767961620788-174722978.jpeg","accommodation":"Kitela Lodge","meals":"All meals included All drinks (Except for spirits/liquor)"},{"day":3,"title":"Tarangire National Park","description":"Spend the day exploring Tarangire National Park, a peaceful haven known for its ancient baobab trees and large elephant herds. As you drive through the golden plains, you’ll spot giraffes, zebras, and maybe even a pride of lions making every moment feel like an unforgettable safari adventure.","image":"https://mambeu.safezonetz.com/uploads/1767961819054-12702650.jpeg","accommodation":"Kitela Lodge","meals":"All meals included All drinks (Except for spirits/liquor)"},{"day":4,"title":"Ngorongoro Crater","description":"On your last day, explore the magnificent Ngorongoro Crater, teeming with wildlife from lions to flamingos. Take in the incredible scenery during your game drive, then relax as you’re driven back to Arusha, where your safari concludes with a drop-off at your hotel or the airport.","image":"","accommodation":"No accommodation (End of tour)","meals":"Breakfast & lunch (Dinner not included) All drinks (Except for spirits/liquor)"}],"highlights":[],"included":["Park fees","(For non-residents)","All activities","(Unless labeled as optional)","All accommodation","(Unless listed as upgrade)","A professional driver/guide","All transportation","(Unless labeled as optional)","All Taxes/VAT","Roundtrip airport transfer","Meals","(As specified in the day-by-day section)","Drinks","(As specified in the day-by-day section)"],"excluded":["International flights","(From/to home)","Additional accommodation before and at the end of the tour","Tips","(Tipping guideline US$10.00 pp per day)","Personal items","(Souvenirs, travel insurance, visa fees, etc.)","Government imposed increase of taxes and/or park fees","Some meals","(As specified in the day-by-day section)"],"gallery":[],"featured":true,"createdAt":"2026-01-09T12:33:58.652Z","updatedAt":"2026-01-09T12:33:58.652Z","path":"journey-299","style":"Luxury","days":4},{"id":298,"slug":"3-Day Safari- Tarangire, Ngorongoro Crater &Lake Manyara","title":"3-Day Safari- Tarangire, Ngorongoro Crater & Lake Manyara","description":"Embark on an adventure beginning and ending at Kilimanjaro International Airport as you explore Tanzania’s iconic wildlife destinations.","fullDescription":"Embark on an adventure beginning and ending at Kilimanjaro International Airport as you explore Tanzania’s iconic wildlife destinations. Visit Tarangire National Park, the UNESCO-listed Ngorongoro Crater, and scenic Lake Manyara National Park. This unforgettable safari includes airport transfers, a professional driver-guide, all meals and drinking water, park fees, and a private 4x4 safari vehicle with a pop-up roof for comfortable and immersive wildlife viewing.","image":"/assets/tour-298.webp","mapImage":"https://mambeu.safezonetz.com/uploads/1767954249868-121290581.jpg","duration":"3 Days / 2 Nights","airport":"Kilimanjaro International Airport (JRO)","category":"Classic Safari","pricingTiers":[{"people":"1 person","price":1899},{"people":"2 people","price":1143},{"people":"3 people","price":946},{"people":"4 people","price":875},{"people":"5 people","price":793},{"people":"6 people","price":772}],"itinerary":[{"day":1,"title":"Tarangire National Park – Majestic Landscapes & Wildlife Encounters","description":"Arrival in the morning at Kilimanjaro International Airport, you will be warmly welcomed by your driver-guide and transferred to Tarangire National Park. Early arrival is recommended to maximize your safari experience.\n\nThe scenic drive takes approximately two and a half hours, passing through the heart of Tanzania’s stunning landscapes. Upon arrival, your guide will assist with park registration before embarking on your first game drive.\n\nTarangire National Park is renowned for its rich biodiversity and large elephant populations. Its varied landscapes range from seasonal swamps to open savannah, with the Tarangire River flowing through the park. You might witness a lion stalking its prey or spot leopards lounging in the branches above.\n\nIn the afternoon, you’ll enjoy your packed lunch inside the park. By 4:00 PM, your game drive will come to an end, and you’ll drive to your lodge for dinner, relaxation, and an overnight stay.","image":"https://mambeu.safezonetz.com/uploads/1767954748041-923575476.jpeg","accommodation":"Foresight Eco Lodge","meals":"Lunch & dinner (Breakfast not included) All drinks (Except for spirits/liquor)"},{"day":2,"title":"Ngorongoro Crater – The Big Five Adventure","description":"Wake up to a stunning morning and enjoy a delicious breakfast before departing at 6:30 AM. for the Ngorongoro Crater.\n\nYou will spend the day exploring this extraordinary natural wonder, discovering the rich diversity of wildlife that inhabits the crater floor. After lunch, you will continue with an afternoon game drive until late afternoon.\n\nThe centerpiece of Ngorongoro is its vast volcanic crater—the largest intact, unflooded caldera in the world. Measuring approximately 20 kilometers in diameter, 600 meters deep, and covering about 300 square kilometers, it is a truly breathtaking natural phenomenon. During the exploration, you will visit Lake Magadi, a shallow alkaline lake located in the southwestern part of the crater, renowned for sightings of black rhinos, flamingos, hippos, and a wide variety of other water birds.\n\nAfter game drive, you will return to your accommodation, where dinner and a restful overnight stay await.","image":"https://mambeu.safezonetz.com/uploads/1767954932665-111630313.jpg","accommodation":"Foresight Eco Lodge","meals":"All meals included All drinks (Except for spirits/liquor)"},{"day":3,"title":"Lake Manyara National Park Scenic Landscapes & Tree-Climbing Lions","description":"Start your day as you head out for Lake Manyara National Park, marking the final day of your safari adventure.\n\nLocated at the base of the Great Rift Valley, Lake Manyara National Park is renowned for its diverse landscapes and abundant wildlife. The Park is especially famous for its tree-climbing lions, as well as sightings of elephants, giraffes, and a wide variety of birdlife drawn to the alkaline waters of Lake Manyara. You will enjoy a rewarding game drive through lush groundwater forests, open plains, and lakeshore habitats.\n\nAfter your visit, you will continue on to Kilimanjaro International Airport, where your safari comes to an end. Depending on your flight schedule, you may arrive earlier to allow for a smooth departure.","image":"","accommodation":"No Accommodation (end of tour)","meals":"Breakfast & lunch (Dinner not included) All drinks (Except for spirits/liquor)"}],"highlights":[],"included":["Park fees","(For non-residents)","All activities","(Unless labeled as optional)","All accommodation","(Unless listed as upgrade)","A professional driver/guide","All transportation","(Unless labeled as optional)","All Taxes/VAT","Roundtrip airport transfer","Meals","(As specified in the day-by-day section)","Drinks","(As specified in the day-by-day section)"],"excluded":["Park fees","(For non-residents)","All activities","(Unless labeled as optional)","All accommodation","(Unless listed as upgrade)","A professional driver/guide","All transportation","(Unless labeled as optional)","All Taxes/VAT","Roundtrip airport transfer","Meals","(As specified in the day-by-day section)","Drinks","(As specified in the day-by-day section)"],"gallery":[],"featured":true,"createdAt":"2026-01-09T10:24:38.390Z","updatedAt":"2026-01-09T10:41:40.552Z","path":"journey-298","style":"Comfort","days":3},{"id":297,"slug":"5-Day Tanzania Luxury Safari","title":"5-Day Tanzania Luxury Safari","description":"Explore northern Tanzania on a thrilling safari with Mambeu Safaris.","fullDescription":"Explore northern Tanzania on a thrilling safari with Mambeu Safaris. Visit the Serengeti’s vast plains filled with wildlife, marvel at Lake Manyara with its flamingos and tree-climbing lions, and discover the Ngorongoro Crater, where you may see the Big Five in a single day. With expert guides and carefully crafted itineraries, enjoy an unforgettable journey through Tanzania’s stunning landscapes and create lasting memories.","image":"/assets/tour-297.webp","mapImage":"https://mambeu.safezonetz.com/uploads/1767882182856-504458906.jpg","duration":"4 Nights / 5 Days","airport":"Kilimanjaro International Airport (JRO)","category":"Luxury Safari","pricingTiers":[{"people":"1 person","price":4301},{"people":"2 people","price":3380},{"people":"3 people","price":3095},{"people":"4 people","price":2951},{"people":"5 people","price":2866},{"people":"6 people","price":2808}],"itinerary":[{"day":1,"title":"Arusha to Lake Manyara National Park","description":"Pick up from your hotel in Arusha at 8:30 AM and drive to Lake Manyara National Park, enjoy full day game drive with picnic lunch.\n\nLake Manyara is a shallow, alkaline lake at the base of the Western Rift Valley escarpment. The park entrance leads to a beautiful groundwater forest. This park is known for its large elephant population. The lions are present, but not seen that easily. The forest patch is home to habituated troops of olive baboon and blue monkey. Buffalo, giraffe and several antelope species are easily encountered on a drive.\n\nThe game drive ends at 4:00 PM, after which you will drive to your lodge for dinner, relaxation, and an overnight stay.","image":"https://mambeu.safezonetz.com/uploads/1767882443555-864081954.jpg","accommodation":"Mawe Mawe Lodge","meals":"Lunch & dinner (Breakfast not included) All drinks (Except for spirits/liquor)"},{"day":2,"title":"Lake Manyara to Serengeti National Park","description":"After breakfast we head towards the Serengeti National Park, via the beautiful high lying farmland of Karatu and the Ngorongoro Conservation Area. Leaving the highlands behind, we descend into the heart of wild Africa – the Serengeti National Park – with its endless plains, rolling into the distance as far as the eye can see. We head to the central park area, one of the richest wildlife habitats in the park, featuring the Seronera River, which provides a valuable water source to this area and therefore attracts wildlife well representative of most of the Serengeti’s species. We'll stop for lunch and enjoy an afternoon game drive in the Serengeti National Park.\n\nLater, you’ll head to your accommodation for dinner and an overnight stay.","image":"https://mambeu.safezonetz.com/uploads/1767882526366-124870340.jpeg","accommodation":"Kubu Kubu Tented Lodge","meals":"All meals included All drinks (Except for spirits/liquor)"},{"day":3,"title":"Game in Serengeti National Park","description":"Starting your full day game drive by 8 AM after a filling breakfast, you will explore the central portion of the Serengeti National Park today.\n\nThe legendary Serengeti National Park is the most renowned safari destination for its incredible population of lions and leopards. The central portion of the Serengeti – known as Seronera area is one of the richest wildlife habitats in the park. It features the Seronera River, which provides a valuable water source to this area and therefore attracts wildlife well representative of most of the Serengeti’s species.\n\nDuring the off season of the migration, one must really look out for the many lion prides that thrive in this region. The interactions and survival of these lion prides provide an excellent game viewing experience all year round. Along with a picnic lunch during the full day game drive, the game end by around 5PM.\n\nThe long day comes to an end with a heavy dinner and a good night’s rest in your accommodation.","image":"https://mambeu.safezonetz.com/uploads/1767882613168-801214702.jpg","accommodation":"Kubu Kubu Tented Lodge","meals":"All meals included All drinks (Except for spirits/liquor)"},{"day":4,"title":"Serengeti National Park","description":"After an early breakfast, we’ll set out around 6:30 AM for a full 6–7 hours of wildlife exploration in the heart of the legendary Serengeti. This iconic park teems with diverse animals—impalas, buffalo, crocodiles, and hippos roam its landscapes—but it is most celebrated for the Great Migration: sweeping herds of 250,000 zebras, 1.5 million wildebeest, and 500,000 antelopes following the rains in a timeless rhythm. Alongside these vast moving herds, you may encounter formidable predators, including lions, leopards, and cheetahs, as they stalk the plains.\n\nAt the close of your game drive, you’ll return to your lodge nestled within the Serengeti, where you can relax, enjoy a delicious dinner, and spend the night accompanied by the tranquil sounds of the wilderness.","image":"https://mambeu.safezonetz.com/uploads/1767882687312-77589006.jpg","accommodation":"Kubu Kubu Tented Lodge","meals":"All meals included All drinks (Except for spirits/liquor)"},{"day":5,"title":"Game Drive Ngorongoro Crater to Arusha/Moshi","description":"Wake up to a stunning morning and enjoy a delicious breakfast before departing at 6:30 AM for the Ngorongoro Crater. You will spend the day exploring this extraordinary natural wonder, discovering the rich diversity of wildlife that inhabits the crater floor.\n\nThe centerpiece of Ngorongoro is its vast volcanic crater—the largest intact, unflooded caldera in the world. Measuring approximately 20 kilometers in diameter, 600 meters deep, and covering about 300 square kilometers, it is a truly breathtaking natural phenomenon. During the exploration, you will visit Lake Magadi, a shallow alkaline lake located in the southwestern part of the crater, renowned for sightings of black rhinos, flamingos, hippos, and a wide variety of other water birds.\n\nThis is the last leg of your safari, with a 3hr drive left to Arusha. You will be dropped off to your preferred location in Arusha. With an incredible experience and loads of memories to cherish.","image":"","accommodation":"No accomodation (End of tour)","meals":"Breakfast & lunch (Dinner not included) All drinks (Except for spirits/liquor)"}],"highlights":[],"included":["Park fees","(For non-residents)","All activities","(Unless labeled as optional)","All accommodation","(Unless listed as upgrade)","A professional driver/guide","All transportation","(Unless labeled as optional)","All Taxes/VAT","Roundtrip airport transfer","Meals","(As specified in the day-by-day section)","Drinks","(As specified in the day-by-day section)"],"excluded":["International flights","(From/to home)","Additional accommodation before and at the end of the tour","Tips","(Tipping guideline US$10.00 pp per day)","Personal items","(Souvenirs, travel insurance, visa fees, etc.)","Government imposed increase of taxes and/or park fees"],"gallery":[],"featured":true,"createdAt":"2026-01-08T14:33:29.997Z","updatedAt":"2026-01-08T14:33:29.997Z","path":"journey-297","style":"Luxury","days":5},{"id":296,"slug":"4-Day Tanzania Cultural Immersion & Adventure Safari","title":"4-Day Tanzania Cultural Immersion & Adventure Safari","description":"Discover Tanzania’s rich cultural heritage beyond its wildlife.","fullDescription":"Discover Tanzania’s rich cultural heritage beyond its wildlife. Visit traditional villages, meet the Hadzabe and Datoga tribes, savor authentic local cuisine, and explore scenic landscapes from the Rift Valley to Lake Eyasi. This Cultural Immersion Safari offers genuine encounters, active experiences like hiking and cycling, and hands-on participation in daily village life. Enjoy a blend of tradition, adventure, and stunning natural beauty for a truly unique and unforgettable journey.","image":"/assets/tour-296.webp","mapImage":"https://mambeu.safezonetz.com/uploads/1767881287315-409519809.jpg","duration":"3 Nights / 4 Days","airport":"Kilimanjaro International Airport (JRO)","category":"Classic Safari","pricingTiers":[{"people":"1 person","price":2314},{"people":"2 people","price":1687},{"people":"3 people","price":1504},{"people":"4 people","price":1401},{"people":"5 people","price":1401},{"people":"6 people","price":1401}],"itinerary":[{"day":1,"title":"Mto wa Mbu – Village Life & Rift Valley Exploration","description":"In the morning, you will be picked up from your accommodation in Arusha City or from Arusha Airport/Kilimanjaro Airport and depart for Mto wa Mbu, the vibrant gateway to the northern cultural heartlands.\n\n Morning: Guided visit to local villages, engaging with residents, learning traditional\ncrafts, and understanding daily life.\n\n Afternoon: Taste authentic local cuisine prepared by village families, gaining insight\ninto regional flavors.\n\n Late Afternoon: Scenic hike along the Rift Valley escarpments, soaking in panoramic\nviews of fertile farmland and distant mountains.\n\n Evening: Return to lodge for relaxation and reflection.","image":"https://mambeu.safezonetz.com/uploads/1767881483765-575804019.jpg","accommodation":"Manyara Safari Lodge","meals":"Lunch & dinner (Breakfast not included) All drinks (Except for spirits/liquor)"},{"day":2,"title":"Cycling & Waterfall Adventure","description":" Morning: Guided bicycle ride through small villages and lush farmland, observing\ntraditional farming practices.\n\n Late Morning: Hike to a hidden waterfall, enjoy refreshing dips, and capture the natural\nbeauty of the area.\n\n Afternoon: Savor local delicacies for lunch at a community farm or village homestead.\n\n Late Afternoon: Cycle to the lakeshore to enjoy peaceful vistas and reflection before\nreturning to the lodge.\n\n Evening: Cultural storytelling session or traditional music performance at your lodge.","image":"https://mambeu.safezonetz.com/uploads/1767881609463-461475200.jpg","accommodation":"Manyara Safari Lodge","meals":"All meals included All drinks (Except for spirits/liquor)"},{"day":3,"title":"Lake Eyasi – Hadzabe & Datoga Tribal Encounters","description":"Travel to Lake Eyasi, home to Tanzania’s iconic hunter-gatherer communities.\n\n Morning: Visit the Hadzabe tribe, learning their traditional hunting methods and\nparticipating in a guided hunt with them.\n\n Afternoon: Explore the Datoga tribe’s pastoralist lifestyle, witnessing blacksmithing,\nbeadwork, and ancient customs.\n\n Evening: Return to lodge with an opportunity to reflect on the day’s unique cultural\ninsights.","image":"https://mambeu.safezonetz.com/uploads/1767881705832-918525941.jpg","accommodation":"Lake Eyasi Safari Lodge","meals":"All meals included All drinks (Except for spirits/liquor)"},{"day":4,"title":"Return to Arusha – Farewell to the Heartlands","description":" Morning at leisure, with optional short village visit or coffee tasting.\n\n Transfer back to Arusha, enjoying scenic views along the way.\n\n End of safari: Depart for onward travel or extend your stay in Arusha.\nAccommodation (optional for extension):\n\n Midrange: Boutique hotel in Arusha with modern amenities\n\n Luxury: Luxury hotel or villa with personalized service.","image":"https://mambeu.safezonetz.com/uploads/1767881794172-314724541.jpg","accommodation":"","meals":"Breakfast & lunch (Dinner not included) All drinks (Except for spirits/liquor)"}],"highlights":[],"included":["Park fees","(For non-residents)","All activities","(Unless labeled as optional)","All accommodation","(Unless listed as upgrade)","A professional driver/guide","All transportation","(Unless labeled as optional)","All Taxes/VAT","Roundtrip airport transfer","Meals","(As specified in the day-by-day section)","Drinks","(As specified in the day-by-day section)"],"excluded":["International flights","(From/to home)","Additional accommodation before and at the end of the tour","Tips","(Tipping guideline US$10.00 pp per day)","Personal items","(Souvenirs, travel insurance, visa fees, etc.)","Government imposed increase of taxes and/or park fees"],"gallery":[],"featured":true,"createdAt":"2026-01-08T14:17:20.581Z","updatedAt":"2026-01-08T14:17:20.581Z","path":"journey-296","style":"Comfort","days":4},{"id":295,"slug":"2-Day Tanzania Highlight Safari from Zanzibar","title":"2-Day Tanzania Highlight Safari from Zanzibar","description":"Enjoy Tanzania’s top attractions on an exclusive safari to Tarangire National Park and the Ngorongoro Crater.","fullDescription":"Enjoy Tanzania’s top attractions on an exclusive safari to Tarangire National Park and the Ngorongoro Crater. Travel from Zanzibar to explore Tarangire’s iconic baobabs and wildlife, then descend into the Ngorongoro Crater, a UNESCO World Heritage Site famed for its rich animal life and scenery. The tour includes return flights, airport transfers, a professional guide, meals, park fees, drinking water, and a private 4x4 safari vehicle with a pop-up roof.","image":"/assets/tour-295.webp","mapImage":"https://mambeu.safezonetz.com/uploads/1767880298278-286039388.jpg","duration":"1 Night / 2 Days","airport":"Kilimanjaro International Airport (JRO)","category":"Classic Safari","pricingTiers":[{"people":"1 person","price":2016},{"people":"2 people","price":1360},{"people":"3 people","price":1175},{"people":"4 people","price":1085},{"people":"5 people","price":1012},{"people":"6 people","price":992}],"itinerary":[{"day":1,"title":"Flight from Zanzibar to Tarangire National Park","description":"Early in the morning at 6:00 AM—though the exact pickup time may vary depending on your hotel location—our driver will transfer you to the airport for your 8:00 AM flight from Zanzibar to Arusha. After landing at 9:15 AM, your driver-guide will take you to Tarangire National Park. The scenic drive takes approximately an hour and a half from Arusha, passing through the heart of Tanzania’s stunning landscapes.\n\nTarangire National Park is renowned for its rich biodiversity and large elephant populations. Its varied landscapes range from seasonal swamps to open savannah, with the Tarangire River flowing through the park. You might witness a lion stalking its prey or spot leopards lounging in the branches above.\n\nIn the afternoon, you’ll enjoy your packed lunch inside the park.\n\nBy 4:00 PM, your game drive will come to an end, and you’ll return to your lodge for dinner, relaxation, and an overnight stay.","image":"https://mambeu.safezonetz.com/uploads/1767880584394-528582862.jpeg","accommodation":"Manyara Lakeview Oasis","meals":"Lunch & dinner (Breakfast not included) All drinks (Except for spirits/liquor)"},{"day":2,"title":"Game Drive in Ngorongoro Crater and Transfer by Air to Zanzibar","description":"After enjoying a delicious breakfast, you will head to the Ngorongoro Conservation Area for an exciting game drive.\n\nThe Ngorongoro Conservation Area is recognized as a UNESCO World Heritage Site for both its natural beauty and cultural significance. As you descend into the crater, you’ll have an excellent opportunity to see the Big Five—lions, elephants, buffalo, leopards, and black rhinos—along with a variety of birds, including flamingos in the crater’s lakes, and experience the stunning natural scenery. Wildlife sightings can happen in an instant, so stay alert!\n\nIn the afternoon, you’ll head to Arusha Airport for your 4:30 pm flight back to Zanzibar. Upon arrival, our guide will be ready to transfer you to your hotel for dinner and a comfortable overnight stay.","image":"","accommodation":"","meals":"Breakfast & lunch (Dinner not included) All drinks (Except for spirits/liquor)"}],"highlights":[],"included":["Park fees","(For non-residents)","All activities","(Unless labeled as optional)","All accommodation","(Unless listed as upgrade)","A professional driver/guide","All transportation","(Unless labeled as optional)","All Taxes/VAT","Roundtrip airport transfer","Meals","(As specified in the day-by-day section)","Drinks","(As specified in the day-by-day section)"],"excluded":["International flights","(From/to home)","Additional accommodation before and at the end of the tour","Tips","(Tipping guideline US$10.00 pp per day)","Personal items","(Souvenirs, travel insurance, visa fees, etc.)","Government imposed increase of taxes and/or park fees"],"gallery":[],"featured":true,"createdAt":"2026-01-08T13:59:59.973Z","updatedAt":"2026-01-08T13:59:59.973Z","path":"journey-295","style":"Comfort","days":2},{"id":294,"slug":"3-Day Serengeti &Ngorongoro Classic Safari from Zanzibar","title":"3-Day Serengeti & Ngorongoro Classic Safari from Zanzibar","description":"Experience the Serengeti Classic Safari, a short yet thrilling journey into Tanzania’s wildlife.","fullDescription":"Experience the Serengeti Classic Safari, a short yet thrilling journey into Tanzania’s wildlife. Starting and ending in Zanzibar Island, this adventure explores the Ngorongoro Crater and the vast Serengeti plains. With Mambeu Safaris’ expert guides and personalized service, enjoy unforgettable moments and a perfect introduction to Tanzania’s natural wonders. Your adventure begins here.","image":"/assets/tour-294.webp","mapImage":"https://mambeu.safezonetz.com/uploads/1767879107708-452092595.jpg","duration":"3 Days / 2 Nights","airport":"Zanzibar Airport","category":"Classic Safari","pricingTiers":[{"people":"1 person","price":3317},{"people":"2 people","price":2519},{"people":"3 people","price":2263},{"people":"4 people","price":2176},{"people":"5 people","price":2074},{"people":"6 people","price":2044}],"itinerary":[{"day":1,"title":"Air transfer from Zanzibar to the heart of Central Serengeti National Park","description":"At 6:00 AM, you will be picked up from your hotel in Zanzibar and transferred to the airport for your 8:00 AM flight to the Central Serengeti (Seronera Airstrip). Upon arrival at approximately 10:40 AM, you will be met by our professional driver-guide and begin an exciting game drive as you head into Serengeti National Park.\n\nRenowned as one of Africa’s premier wildlife destinations, the Serengeti offers spectacular viewing of abundant animals—herds of buffalo, wildebeest, elephants, giraffes, eland, impalas, and Grant’s gazelles roam its sweeping plains, while majestic predators like lions and leopards are frequently sighted. During your exploration, you’ll pause for a scenic picnic lunch before continuing deeper into the park’s extraordinary landscape.\n\nIn the evening, relax and savor dinner followed by a comfortable overnight stay at the beautiful camp.","image":"https://mambeu.safezonetz.com/uploads/1767879540785-434204241.jpeg","accommodation":"Kubu Kubu Tented Lodge","meals":"Lunch & dinner (Breakfast not included) All drinks (Except for spirits/liquor)"},{"day":2,"title":"Game Drive in Central Serengeti","description":"After a restful night immersed in the rhythms of the wild, you’ll awaken to the melodic chorus of birds in the Central Serengeti. Savor a freshly prepared breakfast before setting out on an early morning game drive at 6:30 AM.\n\nThe day is devoted to seeking out Africa’s legendary Big Five—lion, elephant, buffalo, leopard, and rhino—across the sweeping savanna. Renowned for its remarkable wildlife density, the Serengeti offers unforgettable sightings and exceptional photographic moments.\n\nIn the late afternoon, you’ll depart the Serengeti and journey to Karatu, where a warm dinner and a comfortable overnight stay await you.","image":"https://mambeu.safezonetz.com/uploads/1767879744638-651434628.jpeg","accommodation":"Accommodation to be confirmed in your quotation","meals":"All meals included All drinks (Except for spirits/liquor)"},{"day":3,"title":"Game Drive in Ngorongoro Crater and Transfer by Air to Zanzibar Airport","description":"Begin your day with breakfast before departing at 6:30 a.m. for the Ngorongoro Crater. Spend the day exploring this extraordinary natural wonder, renowned for its dense wildlife population on the crater floor. After lunch, continue with an afternoon game drive until late afternoon, discovering the crater’s diverse landscapes and animals.\n\nThe highlight of Ngorongoro is its vast volcanic crater, the largest intact and unflooded caldera in the world. Measuring about 20 kilometers in diameter, 600 meters deep, and covering approximately 300 square kilometers, it offers breathtaking scenery. During the visit, you will explore Lake Magadi, a shallow alkaline lake in the southwestern part of the crater, known for sightings of black rhinos, hippos, flamingos, and many water bird species.\n\nIn the late afternoon, depart for Arusha Airport for your 4:30 p.m. flight back to Zanzibar. Upon arrival, you will be met and transferred to your hotel to enjoy dinner and a comfortable overnight stay.","image":"","accommodation":"","meals":"Breakfast & lunch (Dinner not included) All drinks (Except for spirits/liquor)"}],"highlights":[],"included":["Park fees","(For non-residents)","All activities","(Unless labeled as optional)","All accommodation","(Unless listed as upgrade)","A professional driver/guide","All transportation","(Unless labeled as optional)","All flights during the tour","All Taxes/VAT","Roundtrip airport transfer","Meals","(As specified in the day-by-day section)","Drinks","(As specified in the day-by-day section)"],"excluded":["International flights","(From/to home)","Additional accommodation before and at the end of the tour","Tips","(Tipping guideline US$10.00 pp per day)","Personal items","(Souvenirs, travel insurance, visa fees, etc.)","Government imposed increase of taxes and/or park fees"],"gallery":[],"featured":true,"createdAt":"2026-01-08T13:44:37.105Z","updatedAt":"2026-01-08T13:44:37.105Z","path":"journey-294","style":"Comfort","days":3},{"id":293,"slug":"4-Day Tanzania Crater Savannah Safari","title":"4-Day Tanzania Crater Savannah Safari","description":"Discover the heart of northern Tanzania’s iconic landscapes, from the majestic Ngorongoro Crater to the elephant-rich plains of Tarangire.","fullDescription":"Discover the heart of northern Tanzania’s iconic landscapes, from the majestic Ngorongoro Crater to the elephant-rich plains of Tarangire. Experience close-up wildlife encounters, witness breathtaking scenery, and unwind in carefully selected luxury lodges and camps, offering a perfect blend of adventure, comfort, and personalized service for discerning travelers.","image":"/assets/tour-293.webp","mapImage":"https://mambeu.safezonetz.com/uploads/1767877924164-855899589.jpg","duration":"3 Nights / 4 Days","airport":"Kilimanjaro International Airport (JRO)","category":"Classic Safari","pricingTiers":[{"people":"1 person","price":2929},{"people":"2 people","price":2140},{"people":"3 people","price":2043},{"people":"4 people","price":1916},{"people":"5 people","price":1916},{"people":"6 people","price":1916}],"itinerary":[{"day":1,"title":"Arusha to Ngorongoro Crater - Africa's Grand Amphitheater","description":"Depart from Arusha and journey toward the Ngorongoro Crater, one of the world’s most spectacular natural wonders, for a full day of wildlife viewing within one of Africa’s most iconic landscapes.\n\nDescend 600 meters into the magnificent Ngorongoro Crater, a UNESCO World Heritage Site often called the “Garden of Eden.” This vast natural amphitheater boasts an exceptional concentration of wildlife—here you’ll encounter lions, elephants, buffalo, hyenas, and even the rare black rhino, while flocks of flamingos shimmer along the shores of Lake Magadi.\n\nYour adventure includes a picnic lunch on the crater floor, surrounded by the rhythms of the wild. After an unforgettable day of game viewing, you’ll drive to your accommodation, where you’ll enjoy dinner and a restful overnight stay.","image":"https://mambeu.safezonetz.com/uploads/1767878139745-88812999.jpg","accommodation":"Lake Manyara Wildlife Lodge","meals":"Lunch & dinner (Breakfast not included) All drinks (Except for spirits/liquor)"},{"day":2,"title":"Lake Manyara National Park – Lakeside Wildlife & Birdlife","description":"Travel to Lake Manyara, famous for its vibrant flamingos, tree-climbing lions, and a rich diversity of birdlife.\n\n• Embark on morning and afternoon private game drives along the scenic lakeshore, spotting elephants, hippos, and other wildlife.\n\n• Optional guided nature walks or photography excursions allow you to immerse yourself in the park’s serene landscapes and capture stunning images.\n\n• In the evening, unwind at your lodge with panoramic lake views, enjoying exquisite dining featuring authentic local flavors and a tranquil ambiance.","image":"https://mambeu.safezonetz.com/uploads/1767878479439-960725214.jpg","accommodation":"Tarangire Safari Lodge","meals":"All meals included All drinks (Except for spirits/liquor)"},{"day":3,"title":"Tarangire National Park – Majestic Elephants & Baobabs","description":"Enjoy a full day in Tarangire National Park, renowned for its vast elephant herds and iconic baobab trees. The park’s diverse landscapes span multiple vegetation zones, creating a striking setting for wildlife viewing.\n\nThe Tarangire River, the park’s main lifeline, attracts a wide variety of animals including elephants, lions, leopards, giraffes, zebras, buffaloes, antelopes, and abundant birdlife. With the highest concentration of elephants in Tanzania, Tarangire offers exceptional opportunities to observe their social behavior in the wild.\n\nPause for a picnic lunch at a scenic riverside viewpoint, where wildlife sightings may unfold nearby.\n\n• Evening: Enjoy sundowners at the lodge as the sun sets behind ancient baobab tree.","image":"https://mambeu.safezonetz.com/uploads/1767878601329-834963347.jpg","accommodation":"Tarangire Safari Lodge","meals":"All meals included All drinks (Except for spirits/liquor)"},{"day":4,"title":"Tarangire to Arusha – Farewell to the Wild","description":"Begin your morning at leisure, for a short game drive in Tarangire to catch one last glimpse of the park’s incredible wildlife.\n\nAfter an unforgettable experience of wildlife and scenery, enjoy a scenic drive back to Arusha, taking in the stunning landscapes and reflecting on your safari adventures.\n\nYou will then continue your journey to Arusha or Kilimanjaro International Airport, where your safari comes to an end. Depending on your flight schedule, you may arrive earlier to ensure a smooth and relaxed departure.\n\n• Conclude your unforgettable journey by continuing onward to your next destination, or extend your stay in Arusha to further explore the city and its surrounding areas.","image":"","accommodation":"","meals":"Breakfast & lunch (Dinner not included) Drinks not included"}],"highlights":[],"included":["Park fees","(For non-residents)","All activities","(Unless labeled as optional)","All accommodation","(Unless listed as upgrade)","A professional driver/guide","All transportation","(Unless labeled as optional)","All Taxes/VAT","Roundtrip airport transfer","Meals","(As specified in the day-by-day section)","Drinks","(As specified in the day-by-day section)"],"excluded":["International flights","(From/to home)","Additional accommodation before and at the end of the tour","Tips","(Tipping guideline US$10.00 pp per day)","Personal items","(Souvenirs, travel insurance, visa fees, etc.)","Government imposed increase of taxes and/or park fees"],"gallery":[],"featured":true,"createdAt":"2026-01-08T13:24:58.759Z","updatedAt":"2026-01-08T13:24:58.759Z","path":"journey-293","style":"Comfort","days":4},{"id":292,"slug":"8-Day Calving Season Wildlife Safari (Dec - March)","title":"8-Day Calving Season Wildlife Safari (Dec - March)","description":"Journey through Tanzania’s most iconic landscapes, from the elephant-rich plains of Tarangire to the vast Serengeti and the wildlife-rich Ndutu region during calving season.","fullDescription":"Journey through Tanzania’s most iconic landscapes, from the elephant-rich plains of Tarangire to the vast Serengeti and the wildlife-rich Ndutu region during calving season. Explore the UNESCO-listed Ngorongoro Crater, home to the legendary Big Five, before unwinding on the pristine beaches of Zanzibar. Blending exceptional wildlife encounters with luxurious comfort, this safari offers an unforgettable and perfectly balanced adventure.","image":"/assets/tour-292.webp","mapImage":"https://mambeu.safezonetz.com/uploads/1767876480381-840179422.jpg","duration":"8 Days / 7 Nights","airport":"Kilimanjaro International Airport (JRO)","category":"Classic Safari","pricingTiers":[{"people":"1 person","price":6332},{"people":"2 people","price":4428},{"people":"3 people","price":4206},{"people":"4 people","price":3996},{"people":"5 people","price":3905},{"people":"6 people","price":3788}],"itinerary":[{"day":1,"title":"Tarangire National Park - Arrival First Game Encounters","description":"Arrival in Arusha, embark on a scenic drive to Tarangire National Park, celebrated for its impressive elephant herds and striking baobab trees.\n\n· Embark on a private game drive, customized to your interests, allowing you to spot a variety of wildlife, observe fascinating behaviors, and capture unforgettable photographs.\n\n· As the day winds down, relax with sunset cocktails at a secluded vantage point, taking in the tranquil beauty of the park, its vast landscapes, and the mesmerizing play of colors across the savannah.","image":"https://mambeu.safezonetz.com/uploads/1767876696495-291078920.jpg","accommodation":"Tanzania Bush Camps - Ndutu Mobile Camp","meals":"Lunch & dinner (Breakfast not included) All drinks (Except for spirits/liquor)"},{"day":2,"title":"Ngorongoro Crater - Africa's Natural Amphitheater","description":"Descend into the spectacular Ngorongoro Crater for a full-day private safari, where you can witness lions, rhinos, zebras, and flamingos roaming one of Africa’s most breathtaking landscapes.\n\n· Savor a gourmet bush lunch with panoramic views of the crater, prepared by your personal chef, surrounded by the sights and sounds of the wild.\n\n· In the evening, unwind at your lodge perched on the crater’s edge, with options for stargazing under the pristine African sky or enjoying an intimate dinner on your private terrace, soaking in the dramatic scenery.","image":"https://mambeu.safezonetz.com/uploads/1767876844321-105324331.jpg","accommodation":"Tanzania Bush Camps - Ndutu Mobile Camp","meals":"All meals included All drinks (Except for spirits/liquor)"},{"day":3,"title":"Ndutu – The Heart of the Plains","description":"Drive to Ndutu, a wildlife-rich region famous for its incredible concentrations of animals during the Great Migration.\n\n· Embark on morning and afternoon game drives across the expansive savannah, witnessing wildebeests, zebras, and predators in their natural habitat, capturing unforgettable wildlife moments.\n\n· As the sun sets, unwind at your lodge or luxury tented camp, reflecting on the day’s extraordinary encounters while enjoying the serene beauty of the surrounding plains.","image":"https://mambeu.safezonetz.com/uploads/1767876945969-257699736.jpg","accommodation":"Tanzania Bush Camps - Ndutu Mobile Camp","meals":"All meals included All drinks (Except for spirits/liquor)"},{"day":4,"title":"Ndutu – Migration & Predator Paradise","description":"Spend a full day in Ndutu, exploring the key migration hotspots and areas teeming with predators.\n\n· Embark on expertly guided game drives in search of lions, cheetahs, and the dramatic wildebeest crossings, capturing unforgettable wildlife moments.\n\n· In the afternoon, enjoy optional nature walks or a dedicated photography session, taking advantage of the golden light that bathes the vast plains, creating perfect conditions for stunning shots and immersive encounters with the African wilderness.","image":"https://mambeu.safezonetz.com/uploads/1767877029802-132503567.jpg","accommodation":"Tanzania Bush Camps - Ndutu Mobile Camp","meals":"All meals included Drinks not included"},{"day":5,"title":"Serengeti Plains – Endless Wildlife","description":"Depart from your accommodation and head into the heart of Serengeti National Park, where endless plains meet iconic landscapes and wildlife abounds.\n\n· Enjoy private game drives, encountering majestic lions, towering elephants, graceful giraffes, and vast herds of zebras and wildebeests in their natural habitat.\n\n· As the day winds down, relax with a sunset sundowner atop a scenic kopje, taking in the sweeping vistas of the African plains and the breathtaking colors of the Serengeti sky.","image":"https://mambeu.safezonetz.com/uploads/1767877136980-739112957.png","accommodation":"Serengeti Kati Kati Tented Camp","meals":"All meals included All drinks (Except for spirits/liquor)"},{"day":6,"title":"Serengeti – Hot-Air Balloon & Aerial Adventure","description":"Begin the day with an optional sunrise hot-air balloon ride, drifting over Serengeti plains for breathtaking aerial views of the wildlife below.\n\n· Post-flight champagne breakfast in the bush.\n\n· Continue with a morning and afternoon game drive before returning to your lodge for a luxurious evening.","image":"https://mambeu.safezonetz.com/uploads/1767877261353-343880268.jpg","accommodation":"Serengeti Kati Kati Tented Camp","meals":"All meals included All drinks (Except for spirits/liquor)"},{"day":7,"title":"Serengeti – Final Safari Moments","description":"Spend your final day in the Serengeti with morning and afternoon game drives, savoring every opportunity to witness wildlife in their natural habitat and capture unforgettable photographs.\n\n· As the day winds down, relax at your lodge, reflecting on your safari adventures and preparing for your onward journey to the idyllic island paradise of Zanzibar.","image":"https://mambeu.safezonetz.com/uploads/1767877359684-556197097.jpg","accommodation":"Serengeti Kati Kati Tented Camp","meals":"All meals included All drinks (Except for spirits/liquor)"},{"day":8,"title":"Serengeti to Zanzibar – Tropical Finale","description":"Transfer to Airport for your scenic flight to Zanzibar.\n\n· Upon arrival, unwind on the island’s pristine beaches or onward arrangements.\n\n· Conclude your extraordinary safari journey with lasting memories of the Serengeti’s wild plains, intimate wildlife encounters, and the comfort of exceptional lodges, leaving you with experiences that will stay with you forever.","image":"","accommodation":"","meals":"Breakfast (Lunch & dinner not included) All drinks (Except for spirits/liquor)"}],"highlights":[],"included":["Park fees","(For non-residents)","All activities","(Unless labeled as optional)","All accommodation","(Unless listed as upgrade)","A professional driver/guide","All transportation","(Unless labeled as optional)","All flights during the tour","All Taxes/VAT","Roundtrip airport transfer","Meals","(As specified in the day-by-day section)","Drinks"],"excluded":["International flights","(From/to home)","Additional accommodation before and at the end of the tour","Tips","(Tipping guideline US$10.00 pp per day)","Personal items","(Souvenirs, travel insurance, visa fees, etc.)","Government imposed increase of taxes and/or park fees","Some meals","(As specified in the day-by-day section)"],"gallery":[],"featured":true,"createdAt":"2026-01-08T12:51:58.007Z","updatedAt":"2026-01-08T13:06:28.395Z","path":"journey-292","style":"Comfort","days":8},{"id":291,"slug":"5-Day Ndutu Wildebeest Calving Season (Dec - March)","title":"5-Day Ndutu Wildebeest Calving Season (Dec - March)","description":"This 5-day, 4-night safari begins and ends at Kilimanjaro International Airport, taking you through the stunning landscapes of Lake Manyara and the southern Serengeti (Ndutu).","fullDescription":"This 5-day, 4-night safari begins and ends at Kilimanjaro International Airport, taking you through the stunning landscapes of Lake Manyara and the southern Serengeti (Ndutu). Explore Ngorongoro Crater, a UNESCO World Heritage Site, and witness the spectacular calving season in Ndutu. Your journey also includes iconic highlights such as Ngorongoro Crater, where you’ll have the chance to encounter the legendary Big Five in their natural habitat.","image":"/assets/tour-291.webp","mapImage":"https://mambeu.safezonetz.com/uploads/1767874781601-493018843.jpg","duration":"5 Days / 4 Nights","airport":"Kilimanjaro International Airport (JRO)","category":"Migration Safari","pricingTiers":[{"people":"1 person","price":3105},{"people":"2 people","price":2175},{"people":"3 people","price":1980},{"people":"4 people","price":1859},{"people":"5 people","price":1700},{"people":"6 people","price":1659}],"itinerary":[{"day":1,"title":"Arrival I Arusha","description":"Jambo and welcome to Tanzania!\nUpon arrival at Kilimanjaro International Airport, you will be warmly welcomed by our driver and transferred to Arusha, marking the official start of your safari adventure. After a brief introduction, you will proceed to your accommodation, where you will hear fascinating stories and learn about the local people and their rich culture—offering a perfect first glimpse of Tanzanian life before your journey into the wilderness begins.","image":"https://mambeu.safezonetz.com/uploads/1767875153081-293431916.jpg","accommodation":"Arusha Planet Lodge","meals":"Dinner (Breakfast & lunch not included) Drinking water (Other drinks not included)"},{"day":2,"title":"Arusha to Ndutu Area","description":"Begin your day with an early breakfast before setting out on a thrilling wildlife game drive in the Southern Serengeti (Ndutu area) to witness the spectacular wildebeest calving season. Depart from Arusha and journey toward the Ndutu area, where the southern plains of the Serengeti meet the Ngorongoro Conservation Area.\n\nThe Ndutu calving season, a pinnacle of the Great Wildebeest Migration, typically takes place from late January to March. During this period, over 400,000 wildebeest calves are born, drawn to the lush, nutrient-rich grasses that flourish after the short rains. The Southern Serengeti and Ndutu transform into a vibrant nursery, where newborns are safeguarded—and hunted—amid the presence of predators such as lions, cheetahs, and hyenas.\n\nAfter an immersive day tracking the herds, a packed lunch will be served at a scenic picnic spot within the park. As the day draws to a close, you’ll return to your accommodation for dinner and an overnight stay.","image":"https://mambeu.safezonetz.com/uploads/1767875480473-657016947.jpg","accommodation":"Ndutu Kati Kati Tented Camp","meals":"All meals included All drinks (Except for spirits/liquor)"},{"day":3,"title":"Full-Day Safari in the Southern Serengeti","description":"Enjoy a full day in the beautiful Ndutu plains, where wildlife is everywhere you look. During the calving season, the area bursts with new life as thousands of wildebeest welcome their young, while predators like lions and cheetahs roam nearby. Spend the day exploring at your own pace, taking in the sights, sounds, and pure magic of the wild before returning to camp for a peaceful evening under the stars.","image":"https://mambeu.safezonetz.com/uploads/1767875673444-615631520.jpg","accommodation":"Ndutu Kati Kati Tented Camp","meals":"All meals included All drinks (Except for spirits/liquor)"},{"day":4,"title":"Ndutu to Ngorongoro Crater","description":"After an early breakfast, depart from the lodge and journey toward the spectacular Ngorongoro Conservation Area.\nYou’ll descend nearly 600 meters into the legendary Ngorongoro Crater—a UNESCO World Heritage Site often celebrated as the “Garden of Eden.” Spend the day on an unforgettable game drive within this vast natural amphitheater, renowned for its extraordinary concentration of wildlife. Expect encounters with lions, elephants, buffalo, hyenas, the rare black rhino, and vibrant flocks of flamingos coloring the waters of Lake Magadi. A scenic picnic lunch on the crater floor crowns this remarkable experience before you ascend the crater rim.","image":"https://mambeu.safezonetz.com/uploads/1767875917860-431427283.jpg","accommodation":"Tloma Lodge","meals":"All meals included All drinks (Except for spirits/liquor)"},{"day":5,"title":"Lake Manyara National Park","description":"On your final day, explore the lush landscapes of Lake Manyara National Park, famous for its flamingos, baboons, and tree-climbing lions. Enjoy a morning game drive, taking in the park’s scenic beauty and diverse wildlife. In the evening, depart for Arusha, where you’ll be dropped off at your hotel or the airport, bringing your unforgettable Tanzanian safari to a memorable close.","image":"","accommodation":"","meals":"Breakfast & lunch (Dinner not included) All drinks (Except for spirits/liquor)"}],"highlights":[],"included":["Park fees","(For non-residents)","All activities","(Unless labeled as optional)","All accommodation","(Unless listed as upgrade)","A professional driver/guide","All transportation","(Unless labeled as optional)","All Taxes/VAT","Roundtrip airport transfer","Meals","(As specified in the day-by-day section)","Drinks","(As specified in the day-by-day section)"],"excluded":["International flights","(From/to home)","Additional accommodation before and at the end of the tour","Tips","(Tipping guideline US$10.00 pp per day)","Personal items","(Souvenirs, travel insurance, visa fees, etc.)","Government imposed increase of taxes and/or park fees","Some meals","(As specified in the day-by-day section)"],"gallery":[],"featured":true,"createdAt":"2026-01-08T12:42:32.941Z","updatedAt":"2026-01-08T13:07:18.769Z","path":"journey-291","style":"Comfort","days":5},{"id":62,"slug":"4-days-tanzania-luxury-safari","title":"4 Days Tanzania Luxury Safari","description":"Indulge in a premium 4-day safari experience with luxury lodges, gourmet dining, and exclusive wildlife encounters in Tanzania.","fullDescription":"Experience Tanzania's finest wildlife destinations in ultimate comfort and style with this exclusive 4-day luxury safari. Stay in world-class lodges and tented camps, enjoy gourmet cuisine, and explore the wilderness with expert guides.\n\nThis premium safari takes you through Tarangire National Park, Ngorongoro Crater, and Lake Manyara, offering intimate wildlife encounters and breathtaking landscapes from the comfort of luxury accommodations.","image":"/assets/tour-62.webp","mapImage":"https://mambeusafaris.com/wp-content/uploads/2024/03/rafiki4days.webp","duration":"4 Days / 3 Nights","airport":"Kilimanjaro International Airport (JRO)","category":"Luxury Safari","pricingTiers":[{"people":"1 person","price":4250},{"people":"2 people","price":3026},{"people":"3 people","price":2880},{"people":"4 people","price":2700},{"people":"5 people","price":2679},{"people":"6 people","price":2594}],"itinerary":[{"day":1,"title":"Arusha – Lake Manyara National Park","description":"After a short briefing in the morning, you set off to the Lake Manyara National Park. The small park stretches along the 600 m high Rift Valley Escarpment and is dominated by the alkaline Lake Manyara. It is here where thousands of flamingos seem to colour the shallow waters pink. Many water birds gather at the lake and more than 400 bird species are found in the park.\n\nThe diverse vegetation provides a habitat for many animals such as monkeys in the forest, giraffes and antelopes on the grasslands and elephants around the acacia trees. If you are very lucky you might also see the Manyara lions, lounging in the trees. In the late afternoon you will leave the Lake Manyara National Park and head to the Kirurumu Manyara Lodge, where you will spend the night.","image":"https://mambeusafaris.com/wp-content/uploads/2024/03/Serengeti-Migration-Safari-5-1.jpg","accommodation":"","meals":""},{"day":2,"title":"Lake Manyara – Serengeti National Park","description":"After breakfast you will drive towards the fertile crater highlands where the Iraqw people grow wheat, corn and coffee. You will pass the Ngorongoro Crater before you reach the plains of the Serengeti National Park around midday. The Serengeti is the largest park in Tanzania and has a diversity of habitats and landscapes including short grass plains, savannah, thick bush, swamps, mountains and lakes. Bizarre rock formations called Kopjes dot the grassy landscape where predators are often seen. Depending on the season you will witness the migration of thousands of animals which this park is famous for.\n\nDuring the short rainy season in November and December the herds move from the hills in the north to the plains in the south. During the longer rainy season from April to June they return up north. This circle of life is completely dependent on the yearly rainfalls and the locations of the herds may vary from year to year but your guide will know where to find the animals and where to see them best. You will spend the night at the Kati Kati Tented Camp.","image":"https://mambeusafaris.com/wp-content/uploads/2024/03/Wildlife-Safari-54.jpg","accommodation":"","meals":"Breakfast, Lunch"},{"day":3,"title":"Serengeti – Ngorongoro Crater","description":"Dawn is a good time to watch wildlife and so you will be up early to join an early morning game drive. You will return to the camp for breakfast before heading out for another game drive in the park. Here in the Seronera region you will often see wildebeests and zebras in close proximity of lions and other predators such as leopards and cheetahs. After a picnic lunch you will continue your journey towards the Ngorongoro Crater. Once you have reached the crater rim you will enjoy fantastic views of this 600 m deep collapsed volcano. You will stay at the Ang’ata Ngorongoro Camp, situated on the crater rim","image":"https://mambeusafaris.com/wp-content/uploads/2024/03/Wildlife-Safari-5.jpg","accommodation":"Serena Hotel","meals":"Lunch, Dinner"},{"day":4,"title":"Ngorongoro Crater – Arusha/Airport","description":"After an early breakfast you will drive down the steep and narrow road that takes you into the crater. The slopes are forested but soon the landscape changes to savannah. Here the wildlife is just breath-taking and with a little luck you can observe the Big Five – lion, elephant, buffalo, rhino and leopard – in just a few hours. You should also see warthogs, wildebeests, zebras, hippos and some of the more than 500 bird species of the area. After a morning dedicated to game viewing and a picnic lunch, you will leave the crater in the early afternoon to drive back to Arusha, where you will arrive in the early evening.","image":"","accommodation":"","meals":""}],"highlights":["Luxury lodge accommodations throughout","Tarangire elephant herds","Ngorongoro Crater - the world's largest intact caldera","Big Five game viewing","Gourmet dining experiences","Sundowner cocktails with crater views","Private 4x4 safari vehicle"],"included":["VIP airport transfers","All park entrance fees","Luxury lodge accommodations","Full board with premium drinks","Private professional guide","Private 4x4 luxury safari vehicle","Flying doctor emergency evacuation","All game drives","Crater service fee"],"excluded":["International flights","Visa fees","Travel insurance","Tips and gratuities","Personal expenses","Optional activities"],"gallery":[],"featured":true,"createdAt":"2025-12-24 10:50:01","updatedAt":"2026-03-16T15:15:59.036Z","path":"journey-62","style":"Luxury","days":4},{"id":63,"slug":"3-days-serengeti-classic-safari","title":"3 Days Serengeti Classic Safari","description":"Embrace the thrill of the Serengeti Classic Safari, where Tanzania’s most captivating wildlife experiences await you in a short, exhilarating trip. This safari is your gateway to a rich tapestry of Africa’s natural wonders, offering a complete glimpse into the heart of Tanzania’s wildlife. Perfectly designed for those on brief visits, including business travelers and Kilimanjaro trekkers who crave a touch of the wild, this adventure ensures you make the most of your time in Tanzania.","fullDescription":"Embrace the thrill of the Serengeti Classic Safari, where Tanzania’s most captivating wildlife experiences await you in a short, exhilarating trip. This safari is your gateway to a rich tapestry of Africa’s natural wonders, offering a complete glimpse into the heart of Tanzania’s wildlife. Perfectly designed for those on brief visits, including business travelers and Kilimanjaro trekkers who crave a touch of the wild, this adventure ensures you make the most of your time in Tanzania.\n\nWhether you’re concluding a Zanzibar beach holiday or finishing another Tanzanian adventure, the Serengeti Classic Safari promises a memorable journey through the iconic Ngorongoro Crater and the endless plains of the Serengeti. This compact yet immersive experience provides a breathtaking introduction to the highlights of Tanzania’s northern circuit, making it an ideal choice for anyone looking to add a dose of wildlife magic to their travels.\n\nFor an extraordinary adventure that promises awe-inspiring moments and lasting memories, choose Mambeu Safaris. Our expert guides and personalized service ensure that every aspect of your journey is exceptional. Let Mambeu Safaris turn your dream safari into a reality, delivering an unforgettable experience in the heart of Tanzania’s wild beauty. Your adventure begins here—join us and discover the wonders of Tanzania with Mambeu Safaris!","image":"/assets/tour-63.webp","mapImage":"https://mambeusafaris.com/wp-content/uploads/2024/03/rafiki4days.webp","duration":"3 Days / 2 Nights","airport":"Kilimanjaro International Airport (JRO)","category":"Classic Safari","pricingTiers":[{"people":"1 person","price":2428},{"people":"2 people","price":1765},{"people":"3 people","price":1552},{"people":"4 people","price":1483},{"people":"5 people","price":1475},{"people":"6 people","price":1470}],"itinerary":[{"day":1,"title":" Arusha – Ngorongoro Crater","description":"Safari starts/ends in Arusha. Our driver will pick you from your overnight accommodation in Arusha town in the morning at 5:15 am and make your way to Ngorongoro for a full day exploring the crater floor. The area is world-renowned in its reputation and very small in its scale, so you will see other safari-goers. Don’t let that distract you from the beauty of the place or from the fact that this remains one of the only places on earth where you may see all of the Big Five at once: Lion, Leopard, Bull Elephant, African Buffalo, and Black Rhino. To maximize your time on the crater floor you will enjoy a special packed lunch at a scenic picnic spot by the hippo pool. Your journey will take you through this tremendous landscape that is constantly changing as animals move to and fro in search of pasture, water, or easy prey. In the evening drive back to the crater rim for dinner and overnight.","image":"","accommodation":"","meals":""},{"day":2,"title":"Ngorongoro Crater to Serengeti National Park","description":"After an early breakfast in the morning, you will make your way to Serengeti national park for your full-day game drives in the endless pain of Serengeti national park. You will have a great time visiting retima hippo and the crocodile pool. You’ll continue your wildlife viewing for the rest of the day, stopping to enjoy a picnic lunch at your leisure. Full days ‘discover Serengeti’ game drives. The day for the big cats – cheetahs, leopards, and lions. In the evening drive to the camp for dinner and overnight.","image":"","accommodation":"","meals":""},{"day":3,"title":"Serengeti – Arusha","description":"In the morning after breakfast, you will drive out for short SUNRISE to mid-morning game drives in the endless plain of Serengeti before you start your drives back to Arusha with game drives en-route. Accommodations in Arusha are not included, it is at your own arrangements. This is the end of the trip.","image":"","accommodation":"","meals":""}],"highlights":["Endless Serengeti plains","Big cat sightings","Great Migration (seasonal)","Seronera Valley - predator hotspot","African sunrise and sunset","Professional wildlife guide"],"included":["Airport pickup and drop off","Transportation in a 4×4 safari vehicle","Professional, English-speaking guide","Overnight accommodation according to the itinerary","Meals while on safari","Mineral water","All government taxes","All mentioned activities","All national park fees","Flying Doctors insurance (AMREF) during the safari for emergence evacuations"],"excluded":["International or Local Flights","Optional activities","Alcoholic and soft drinks","Visa fees","Tips","Personal spending money for souvenirs etc.","Travel insurance"],"gallery":[],"featured":true,"createdAt":"2025-12-24 10:50:01","updatedAt":"2026-03-16T15:18:05.393Z","path":"journey-63","style":"Comfort","days":3},{"id":64,"slug":"5-days-tanzania-magical-safari","title":"5 Days Tanzania Magic Safari","description":"Experience the magic of Tanzania on this 5-day adventure through Tarangire, Serengeti, and Ngorongoro Crater.","fullDescription":"Embark on a magical 5-day journey through Tanzania's most spectacular wildlife destinations. This comprehensive safari combines the elephant-rich Tarangire, the legendary Serengeti plains, and the breathtaking Ngorongoro Crater.\n\nExperience diverse ecosystems, incredible wildlife concentrations, and the raw beauty of East Africa. This safari offers the perfect balance of adventure and comfort, with opportunities to see the Big Five and countless other species.","image":"/assets/tour-64.webp","mapImage":"https://mambeusafaris.com/wp-content/uploads/2024/03/rafiki4days.webp","duration":"5 Days / 4 Nights","airport":"Kilimanjaro International Airport (JRO)","category":"Classic Safari","pricingTiers":[{"people":"1 person","price":3910},{"people":"2 people","price":3073},{"people":"3 people","price":2814},{"people":"4 people","price":2683},{"people":"5 people","price":2605},{"people":"6 people","price":2553}],"itinerary":[{"day":1,"title":"Arusha to Lake Manyara National Park","description":"Pick up from your hotel in Arusha at 8:30 AM and drive to Lake Manyara National Park, enjoy full day game drive with picnic lunch. Lake Manyara is a shallow, alkaline lake at the base of the Western Rift Valley escarpment. The park entrance leads to a beautiful groundwater forest. This park is known for its large elephant population. The lions are present, but not seen that easily. The forest patch is home to habituated troops of olive baboon and blue monkey. Buffalo, giraffe and several antelope species are easily encountered on a drive.","image":"https://mambeusafaris.com/wp-content/uploads/2024/03/Wildlife-Safari-41.jpg","accommodation":"","meals":""},{"day":2,"title":" Lake Manyara to Serengeti National Park","description":"After breakfast we head towards the Serengeti National Park, via the beautiful high lying farmland of Karatu and the Ngorongoro Conservation Area. Leaving the highlands behind, we descend into the heart of wild Africa – the Serengeti National Park – with its endless plains, rolling into the distance as far as the eye can see. We head to the central park area, known as the Seronera area, one of the richest wildlife habitats in the park, featuring the Seronera River, which provides a valuable water source to this area and therefore attracts wildlife well representative of most of the Serengeti’s species. We arrive in time for lunch and enjoy an afternoon game drive in the Serengeti National Park.","image":"https://mambeusafaris.com/wp-content/uploads/2024/03/Wildlife-Safari-43.jpg","accommodation":"","meals":""},{"day":3,"title":"Serengeti National Park","description":"Starting your full day game drive by 8 AM after a filling breakfast, you will explore the central portion of the Serengeti National Park today. The legendary Serengeti National Park is the most renowned safari destination for its incredible population of lions and leopards. The central portion of the Serengeti – known as Seronera area is one of the richest wildlife habitats in the park. It features the Seronera River, which provides a valuable water source to this area and therefore attracts wildlife well representative of most of the Serengeti’s species.\n\nDuring the off season of the migration, one must really look out for the many lion prides that thrive in this region. The interactions and survival of these lion prides provide an excellent game viewing experience all year round. Along with a picnic lunch during the full day game drive, the day will come to a close by around 5PM. The long day comes to an end with a heavy dinner and a good night’s rest in your accommodation.","image":"","accommodation":"","meals":""},{"day":4,"title":"Serengeti to Ngorongoro Conservation Area","description":"After breakfast, you will have a morning game drive in Serengeti National Park. Later depart for Ngorongoro Crater Rim with picnic lunch. Ngorongoro Crater is the largest collapsed volcanic crater in the world and fourteen kilometers of isolated natural beauty. Ngorongoro Crater is surrounded by a ring of extinct volcanoes and the floor, dotted with watering holes, shelters some 30,000 animals. The eventful day comes to an end with a heavy dinner and a good night’s rest in your accommodation.","image":"","accommodation":"","meals":""},{"day":5,"title":"Crater tour (5 hours game drive) to Arusha/Moshi.","description":"On the last day of your safari, you will have an early start. Finishing up with a quick breakfast you will make an early descend at around 6:30 AM into the crater floor. The Ngorongoro Crater is the world’s largest inactive, intact and unfilled volcanic caldera. It has a massive floor of about 260 sq kms with a depth of over 2000 feet. The 5-hour game drive in the crater floor, will show you a lot of animal action.\n\nKeeping the camera ready is definitely recommended. The African elephant, buffalo, Black rhino, Hippos, Hyenas, Cheetahs and Lions are found in plenty. Post the picnic lunch at the beautiful Hippo pool, you will begin a steep ascend to the top exit of the crater. This is the last leg of your safari, with a 4hr drive left to Arusha. You will be dropped off to your preferred location in Arusha by 6:00 PM in the evening. With an incredible experience and loads of memories to cherish, this is the time you bid goodbye to your team.","image":"","accommodation":"","meals":""}],"highlights":["Tarangire elephant herds","Serengeti endless plains","Ngorongoro Crater descent","Big Five opportunities","Diverse ecosystems","Professional guided experience"],"included":["Airport transfers","All park entrance fees","Professional safari guide","4x4 safari vehicle","Full board accommodation","Drinking water","Game drives as per itinerary","Crater service fee"],"excluded":["International flights","Visa fees","Travel insurance","Tips and gratuities","Personal expenses","Alcoholic beverages","Optional activities"],"gallery":[],"featured":true,"createdAt":"2025-12-24 10:50:01","updatedAt":"2026-03-16T15:18:36.559Z","path":"journey-64","style":"Comfort","days":5},{"id":65,"slug":"7-days-serengeti-migration-safari","title":"7 Days Serengeti Migration Safari","description":"Witness the Great Migration on this epic 7-day safari through the Serengeti ecosystem and northern Tanzania.","fullDescription":"Experience one of nature's greatest spectacles - the Great Wildebeest Migration - on this comprehensive 7-day safari adventure. Follow millions of wildebeest and zebra across the Serengeti plains in their eternal search for fresh grasslands.\n\nThis extended safari provides ample time to explore different regions of the Serengeti, witness dramatic river crossings (seasonal), and enjoy diverse wildlife encounters across multiple ecosystems.","image":"/assets/tour-65.webp","mapImage":"https://mambeusafaris.com/wp-content/uploads/2024/03/rafiki4days.webp","duration":"7 Days / 6 Nights","airport":"Kilimanjaro International Airport (JRO)","category":"Migration Safari","pricingTiers":[{"people":"1 person","price":4625},{"people":"2 people","price":3589},{"people":"3 people","price":3177},{"people":"4 people","price":3079},{"people":"5 people","price":2977},{"people":"6 people","price":2902}],"itinerary":[{"day":1,"title":"Arusha – Tarangire National Park","description":"Breakfast before you drive to Tarangire National Park crossing the Maasai Steppe on your way to Tarangire National Park, Tanzania’s fourth-largest and one of its most diverse. Stop at the picturesque park gate for the driver to fill up the park registration book before you enter the park for the evening to sunset game drive in the park enjoying viewing animals.\n\n\n\nElephants, Buffalos, and pythons are seen easily and regularly cross your path, unbothered by your benign presence and going about their daily routines. You’ll meander along bush tracks, explore the Tarangire River’s twists and turns, and find elephants drinking and playing in the refreshing waters. Late this afternoon you’ll arrive at your campsite where you can settle in and relax before dinner and your first night in the bush.\n\n\n\nDinner and overnight at Tarangire Simba tented lodge.","image":"","accommodation":"","meals":""},{"day":2,"title":"Tarangire National – Lake Manyara National Park","description":"Early breakfast before you drive out with game sunrise game drives en-route to Lake Manyara national park. Lake Manyara National Park is among Tanzania’s smallest parks. Drive through the lush garden is a gentle reminder that you are now in Africa. Exotic birdcalls fill the air. Enjoy a picnic lunch and afterward, you’ll continue game viewing of animals in the park.\n\nZebra, wildebeest, bushbuck, dik-dik, and guinea fowl regularly cross your path, unbothered by your benign presence and going about their daily routines. You’ll meander along bush tracks and explore the Lake which is home to thousands of Flamingos and rivers twists and turns, finding elephants drinking and playing in the refreshing waters. More game drives to sunset before you drive to the lodge for dinner and overnight.\n\nNote: In the late afternoon you will do a short hike down the Great Rift Valley as well as a visit to Mto wa Mbu village. View birds, monkeys, bushbucks, and other forest animals. During the hike enjoy the sounds of the forest and the fresh streams and waterfalls surrounding you. Visit the Mto wa Mbu local village. Enjoy a short stroll on the edge of the Great Rift Valley with beautiful views of Lake Manyara and the National Park below. Learn more about plants, insects, birds, and small mammals from a knowledgeable guide.\n\nDinner and overnight at Acacia Farm Lodge.","image":"","accommodation":"","meals":""},{"day":3,"title":"Lake Manyara - Serengeti National Park","description":"After breakfast, you will make your way to Serengeti National Park heading in a northwesterly direction. Head up the winding, switch-back road and into the Ngorongoro Highlands continue to the Serengeti National Park (endless plain) for the afternoon to sunset game drive before heading to your overnight camps for dinner and overnight.\n\nDinner and overnight at Serengeti Sopa Lodge.","image":"","accommodation":"","meals":""},{"day":4,"title":"Central Serengeti Safari","description":"Full days ‘discover Serengeti’ game drives. The day for the big cats – cheetahs, leopards, and lions. Mostly you will go out for a SUNRISE game drive at 0600am followed by b/fast at 0800am. More game drive till Lunchtime (picnic lunch). After your picnic lunch, you will proceed with your afternoon game drive en–route to the Mara River area for dinner and overnight.\n\nDinner and Overnight at Ole Serai tented camp.","image":"","accommodation":"","meals":""},{"day":5,"title":"North Serengeti Mara River Area","description":"Early breakfast before you drive for a full-day game drive in the Serengeti Park. On this day you will try to follow migration groups around the Mara River. In the evening drive back to the lodge for dinner and overnight. Some of the wildebeests’ groups don’t cross the river and you might catch them around the Mara River.\n\nDinner and overnight at Chaka tented camp.","image":"","accommodation":"","meals":""},{"day":6,"title":"North Serengeti Park/Ngorongoro Crater Rim","description":"SUNRISE game drives start at 06:00 am till 9:00 am. When you’ll depart the Mara River area with game drives en route to the Ngorongoro Crater rim for dinner and overnight. On the way, you will visit the Retima hippo pool.\n\nDinner and overnight at Ngorongoro lion paw lodge.","image":"","accommodation":"","meals":""},{"day":7,"title":"Ngorongoro Crater Floor Back to Arusha","description":"Rise early for breakfast before you spend a full day exploring the crater floor. The area is world-renowned in its reputation and very small in its scale, so you will see other safari-goers. Don’t let that distract you from the beauty of the place or from the fact that this remains one of the only places on earth where you may see all of the Big Five at once: Lion, Leopard, Bull Elephant, African Buffalo, and Black Rhino. To maximize your time on the crater floor you will enjoy a special boxed lunch at a scenic picnic spot.\n\nYour journey will take you through this tremendous landscape that is constantly changing as animals move to and fro in search of pasture, water, or east prey.\n\nIn the afternoon, it is time to depart this Garden of Eden and drive back to Arusha for dinner and overnight","image":"","accommodation":"","meals":""}],"highlights":["Great Wildebeest Migration","River crossing opportunities (seasonal)","Multiple Serengeti ecosystems","Ngorongoro Crater","Predator-prey interactions","Extended wildlife viewing time","Professional migration tracking"],"included":["Airport transfers","All park entrance fees","Professional safari guide","4x4 safari vehicle","Full board accommodation","Drinking water","All game drives","Crater service fee","One night hotel in Arusha"],"excluded":["International flights","Visa fees","Travel insurance","Tips and gratuities","Personal expenses","Alcoholic beverages","Hot air balloon safari","Optional activities"],"gallery":[],"featured":false,"createdAt":"2025-12-24 10:50:01","updatedAt":"2026-03-16T15:19:01.508Z","path":"journey-65","style":"Comfort","days":7},{"id":66,"slug":"6-days-tanzania-joy-safari","title":"6 Days Tanzania Joy Safari","description":"Get ready for a 6-day journey that promises to be nothing short of extraordinary. Our Tanzania Lodge Safari immerses you in the heart of Africa’s wild beauty, offering intimate game safaris that bring you face-to-face with stunning wildlife. Explore the majestic crater, uncovering the secrets of diverse ecosystems and the fascinating creatures that inhabit them.","fullDescription":"Get ready for a 6-day journey that promises to be nothing short of extraordinary. Our Tanzania Lodge Safari immerses you in the heart of Africa’s wild beauty, offering intimate game safaris that bring you face-to-face with stunning wildlife. Explore the majestic crater, uncovering the secrets of diverse ecosystems and the fascinating creatures that inhabit them.\n\nRelax in cozy lodges where the sounds of the savanna will gently awaken you each morning and serenade you each night, creating a truly magical experience. This is more than just a safari; it’s a chance to connect deeply with nature and create unforgettable memories.\n\nFor an unparalleled adventure that combines luxury and excitement, choose Mambeu Safaris. Our expert guides and exceptional service ensure that your journey is seamless and inspiring, leaving you with cherished memories of Tanzania’s breathtaking landscapes and wildlife. Let Mambeu Safaris turn your dream safari into an unforgettable reality.","image":"/assets/hero.webp","mapImage":"https://mambeusafaris.com/wp-content/uploads/2024/03/rafiki4days.webp","duration":"6 Days / 5 Nights","airport":"Kilimanjaro Int. Airport","category":"Classic Safari","pricingTiers":[{"people":"1 person","price":3699},{"people":"2 people","price":2856},{"people":"3 people","price":2566},{"people":"4 people","price":2340},{"people":"5 people","price":2322},{"people":"6 people","price":2190}],"itinerary":[{"day":1,"title":"Arusha – Lake Manyara National Park","description":"0830hrs drive from Arusha to Lake Manyara National Park for game drives with picnic lunch boxes. Lake Manyara is a good soft introduction to the safari experience. It is a magical and pretty park that winds its way around a mainly forested driving route between the banks of Soda Water Lake and the impressive rise of the Great Rift escarpment.","image":"","accommodation":"","meals":""},{"day":2,"title":"Lake Manyara – Serengeti National Park","description":"After breakfast you will drive towards the fertile crater highlands where the Iraqw people grow wheat, corn and coffee. You will pass the Ngorongoro Crater before you reach the plains of the Serengeti National Park around midday. The Serengeti is the largest park in Tanzania and has a diversity of habitats and landscapes including short grass plains, savannah, thick bush, swamps, mountains and lakes. Bizarre rock formations called Kopjes dot the grassy landscape where predators are often seen. Depending on the season you will witness the migration of thousands of animals which this park is famous for.\n\nDuring the short rainy season in November and December the herds move from the hills in the north to the plains in the south. During the longer rainy season from April to June they return up north. This circle of life is completely dependent on the yearly rainfalls and the locations of the herds may vary from year to year but your guide will know where to find the animals and where to see them best.","image":"","accommodation":"","meals":""},{"day":3,"title":"Full Day Serengeti National Park","description":"0630hrs early morning game drives in Serengeti National Park, late breakfast at Lodge, followed by another game drive, dinner and overnight at Public Camping Site","image":"","accommodation":"","meals":""},{"day":4,"title":"Serengeti – Ngorongoro Crater","description":"After breakfast depart for Serengeti park game drives, return for hot lunch at lodge, then drive to Ngorongoro for dinner and overnight at Public Camping Site","image":"","accommodation":"","meals":""},{"day":5,"title":"Ngorongoro Crater – Tarangire National Park","description":"After breakfast Ngorongoro Crater game drives with picnic lunch boxes. The crater is said to have the most-dense concentration of wildlife in Africa. As such, Ngorongoro Crater has achieved world renown, and attracts a growing number of visitors each year. Even if time is limited this natural but accessibly small caldera ensures a rewarding safari. Later afternoon drive to Tarangire National Park for dinner and overnight at Public Camping Site","image":"","accommodation":"","meals":""},{"day":6,"title":"Tarangire National Park – Arusha","description":"After breakfast Tarangire National Park for game drives, Tarangire is well known for its big herds of Elephants and huge baobab trees plus other predators like lions and leopards. Hot lunch at the lodge or picnic lunch at the picnic site, later afternoon drive back to Arusha town and dropped off at Arusha  for dinner and overnight.","image":"","accommodation":"","meals":""}],"highlights":[],"included":["Airport pickup and drop off","Transportation in a 4×4 safari vehicle","Professional, English-speaking guide","Overnight accommodation according to the itinerary","Meals while on safari","Mineral water","All government taxes","All mentioned activities","All national park fees","Flying Doctors insurance (AMREF) during the safari for emergence evacuations"],"excluded":["International or Local Flights","Optional activities","Alcoholic and soft drinks","Visa fees","Tips","Personal spending money for souvenirs etc.","Travel insurance"],"gallery":[],"featured":true,"createdAt":"2025-12-24 10:50:01","updatedAt":"2026-01-08T11:12:33.231Z","path":"journey-66","style":"Comfort","days":6},{"id":67,"slug":"4-days-affordable-camping-safari","title":"4 Days Affordable Camping Safari","description":"Get a real taste of Tanzania on this safari which will take you right out to Serengeti, a great place to visit any time of year. You will also visit two of Tanzania’s most popular national parks; the Ngorongoro Crater, where you will have the best chance of seeing the Big Five, and either Tarangire National Park or Lake Manyara national Park depending on which will be selling better viewing of animals at that particular time.","fullDescription":"Get a real taste of Tanzania on this safari which will take you right out to Serengeti, a great place to visit any time of year. You will also visit two of Tanzania’s most popular national parks; the Ngorongoro Crater, where you will have the best chance of seeing the Big Five, and either Tarangire National Park or Lake Manyara national Park depending on which will be selling better viewing of animals at that particular time.\n\nThis package welcomes you to Tarangire National Park, Lake Manyara National Park, Serengeti National Park and Ngorongoro Conservation Area. These wilderness areas are characterized by different inhabitant animal behaviors; however, you may see some exceptional attractions that will be sighted on the very specific park and never in another. As Manyara is well known for the tree climbing lions, the soda ash lake and its flamingos, Tarangire is widely famous for its high-density population of Elephants and Baobab Trees. Both Parks are a home to more than Hundreds of bird species and a haven for bird enthusiasts in East Africa.","image":"/assets/hero.webp","mapImage":"https://mambeusafaris.com/wp-content/uploads/2024/03/rafiki4days.webp","duration":"4 Days / 3 Nights","airport":"Kilimanjaro International Airport","category":"Camping Safari","pricingTiers":[{"people":"1 person","price":2568},{"people":"2 people","price":1800},{"people":"3 people","price":1638},{"people":"4 people","price":1530},{"people":"5 people","price":1457},{"people":"6 people","price":1417}],"itinerary":[{"day":1,"title":"Arusha – Lake Manyara National Park","description":"After a short briefing in the morning, you set off to the Lake Manyara National Park. The small park stretches along the 600 m high Rift Valley Escarpment and is dominated by the alkaline Lake Manyara. It is here where thousands of flamingos seem to colour the shallow waters pink. Many water birds gather at the lake and more than 400 bird species are found in the park.\n\nThe diverse vegetation provides a habitat for many animals such as monkeys in the forest, giraffes and antelopes on the grasslands and elephants around the acacia trees. If you are very lucky you might also see the Manyara lions, lounging in the trees. In the late afternoon you will leave the Lake Manyara National Park and head to the campsite, where you will spend the night.","image":"","accommodation":"","meals":""},{"day":2,"title":"Lake Manyara – Serengeti National Park","description":"After breakfast you will drive towards the fertile crater highlands where the Iraqw people grow wheat, corn and coffee. You will pass the Ngorongoro Crater before you reach the plains of the Serengeti National Park around midday. The Serengeti is the largest park in Tanzania and has a diversity of habitats and landscapes including short grass plains, savannah, thick bush, swamps, mountains and lakes. Bizarre rock formations called Kopjes dot the grassy landscape where predators are often seen. Depending on the season you will witness the migration of thousands of animals which this park is famous for.\n\nDuring the short rainy season in November and December the herds move from the hills in the north to the plains in the south. During the longer rainy season from April to June they return up north. This circle of life is completely dependent on the yearly rainfalls and the locations of the herds may vary from year to year but your guide will know where to find the animals and where to see them best.","image":"","accommodation":"","meals":""},{"day":3,"title":"Serengeti – Ngorongoro Crater","description":"Dawn is a good time to watch wildlife and so you will be up early to join an early morning game drive. You will return to the camp for breakfast before heading out for another game drive in the park. Here in the Seronera region you will often see wildebeests and zebras in close proximity of lions and other predators such as leopards and cheetahs. After a picnic lunch you will continue your journey towards the Ngorongoro Crater. Once you have reached the crater rim you will enjoy fantastic views of this 600 m deep collapsed volcano.","image":"","accommodation":"","meals":""},{"day":4,"title":"Ngorongoro Crater – Arusha/Airport","description":"After an early breakfast you will drive down the steep and narrow road that takes you into the crater. The slopes are forested but soon the landscape changes to savannah. Here the wildlife is just breath-taking and with a little luck you can observe the Big Five – lion, elephant, buffalo, rhino and leopard – in just a few hours. You should also see warthogs, wildebeests, zebras, hippos and some of the more than 500 bird species of the area. After a morning dedicated to game viewing and a picnic lunch, you will leave the crater in the early afternoon to drive back to Arusha, where you will arrive in the early evening.","image":"","accommodation":"","meals":""}],"highlights":[],"included":["Airport pickup and drop off","Transportation in a 4×4 safari vehicle","Professional, English-speaking guide","Overnight accommodation according to the itinerary","Meals while on safari","Mineral water","All government taxes","All mentioned activities","All national park fees","Flying Doctors insurance (AMREF) during the safari for emergence evacuations"],"excluded":["International or Local Flights","Optional activities","Alcoholic and soft drinks","Visa fees","Tips","Personal spending money for souvenirs etc.","Travel insurance"],"gallery":[],"featured":true,"createdAt":"2025-12-24 10:50:01","updatedAt":"2026-01-08T11:08:41.595Z","path":"journey-67","style":"Camping","days":4},{"id":68,"slug":"4-days-big-5-tanzania-safari","title":"4 Days Big 5 Tanzania Safari","description":"This safari package offers an exhilarating opportunity to explore the most stunning parks in northern Tanzania. Journey through the Serengeti National Park, famous for its diverse landscapes ranging from the vast grasslands of the southeast to the hilly and rocky terrain in the north, and the valleys, rivers, and forests to the west. This untouched wilderness is home to an impressive array of safari animals in their natural habitat. Additionally, you will visit the Ngorongoro Crater, affectionately known as the “Garden of Animals,” where you have a remarkable chance to see the Big Five all in a single day.","fullDescription":"This safari package offers an exhilarating opportunity to explore the most stunning parks in northern Tanzania. Journey through the Serengeti National Park, famous for its diverse landscapes ranging from the vast grasslands of the southeast to the hilly and rocky terrain in the north, and the valleys, rivers, and forests to the west. This untouched wilderness is home to an impressive array of safari animals in their natural habitat. Additionally, you will visit the Ngorongoro Crater, affectionately known as the “Garden of Animals,” where you have a remarkable chance to see the Big Five all in a single day.\n\nFor an unforgettable safari adventure, choose Mambeu Safaris. Our expert guides and customized itineraries ensure an exceptional experience, guiding you through the wonders of Tanzania’s wild landscapes. Let us help you create memories that will last a lifetime, surrounded by the raw beauty of nature.","image":"/assets/tour-68.webp","mapImage":"https://mambeusafaris.com/wp-content/uploads/2024/03/rafiki4days.webp","duration":"4 Days / 3 Nights","airport":"Kilimanjaro International Airport (JRO)","category":"Big Five Safari","pricingTiers":[{"people":"1 person","price":2687},{"people":"2 people","price":1934},{"people":"3 people","price":1805},{"people":"4 people","price":1670},{"people":"5 people","price":1587},{"people":"6 people","price":1468}],"itinerary":[{"day":1,"title":"Arusha to Serengeti National Park","description":"Pick up at 6:30 AM from your hotel in Arusha and proceed towards Serengeti National Park, via the beautiful high lying farmland of Karatu and the Ngorongoro Conservation Area. Leaving the highlands behind, we descend into the heart of wild Africa – the Serengeti National Park with its endless plains, rolling into the distance as far as the eye can see. We head to the central park area, known as the Seronera area, one of the richest wildlife habitats in the park, featuring the Seronera River, which provides a valuable water source to this area and therefore attracts wildlife well representative of most of the Serengeti’s species. We arrive in time for lunch and enjoy an afternoon game drive in the Serengeti National Park.","image":"https://mambeu.safezonetz.com/uploads/1784125649699-399763390.jpg","accommodation":"","meals":""},{"day":2,"title":"Serengeti National Park","description":"Today you will have a full day game drive in Serengeti with chances to see predators chasing their pray and enjoy their kill. Serengeti is undoubtedly the best-known wildlife sanctuary in the world, unequalled for its natural beauty and scientific value. You will have game drive in the endless plains of the Serengeti with a chance to see the great herds of wildebeest, zebras and gazelles or a pride of lions lounging in the shade.","image":"https://mambeusafaris.com/wp-content/uploads/2024/03/Wildlife-Safari-47.jpg","accommodation":"","meals":""},{"day":3,"title":"Serengeti National Park to Ngorongoro Conservation Area","description":"Enjoy early breakfast and meet your guide to have a last morning game drive in Serengeti National Park, later depart to Ngorongoro Conservation area with en-route game drive and picnic lunch. Ngorongoro is a special conservation area and not a National Park. The whole area is managed for both animals and local Maasai people who graze their cattle alongside the indigenous wildlife.","image":"https://mambeu.safezonetz.com/uploads/1784125667030-466836822.jpg","accommodation":"","meals":""},{"day":4,"title":"Ngorongoro Crater (5 hrs game drive) & back to Arusha","description":"After breakfast, descend into the crater, enjoy 5 hours game drive in the crater. The Ngorongoro Crater is one of the most densely crowded African wildlife areas in the world and is home to an estimated 30,000 animals including some of Tanzania’s last remaining black rhino.\n\nSupported by a year round water supply and fodder, the crater supports a vast variety of animals, which include herds of wildebeest, zebra, buffalo, eland, warthog, hippo, and giant African elephants. Another big draw card to this picturesque national park is its huge population of predators, which include lions, hyenas, jackals, cheetahs and the ever-elusive leopard. We will enjoy a picnic lunch on the crater floor.\n\nLate afternoon drive back to Arusha and drop off at your hotel.","image":"https://mambeu.safezonetz.com/uploads/1784125673809-380158715.jpg","accommodation":"","meals":""}],"highlights":["Focused Big Five experience","Ngorongoro Crater - Big Five hotspot","Black rhino sightings (rare)","Large elephant herds","Lion prides","Buffalo herds","Leopard opportunities"],"included":["Airport transfers","All park entrance fees","Professional safari guide","4x4 safari vehicle","Full board accommodation","Drinking water","Game drives as per itinerary","Crater service fee"],"excluded":["International flights","Visa fees","Travel insurance","Tips and gratuities","Personal expenses","Alcoholic beverages","Optional activities"],"gallery":[],"featured":true,"createdAt":"2025-12-24 10:50:01","updatedAt":"2026-07-15T14:28:09.391Z","path":"journey-68","style":"Comfort","days":4},{"id":1,"slug":"2-days-tanzania-highlight-safari","title":"2 Days Tanzania Highlight Safari","description":"Set out on an extraordinary journey through Tanzania’s spectacular landscapes with our exclusive tour, showcasing the enchanting beauty of Tarangire National Park and the iconic Ngorongoro Crater. Your adventure begins in Arusha, where our experienced driver guides will warmly welcome you and prepare you for an immersive exploration of the region’s natural wonders. Spend a night amidst the diverse ecosystems of Tarangire National Park, where the majestic baobab trees and a vibrant array of wildlife, from towering elephants to elusive big cats, create an unforgettable safari experience.","fullDescription":"Set out on an extraordinary journey through Tanzania’s spectacular landscapes with our exclusive tour, showcasing the enchanting beauty of Tarangire National Park and the iconic Ngorongoro Crater. Your adventure begins in Arusha, where our experienced driver guides will warmly welcome you and prepare you for an immersive exploration of the region’s natural wonders. Spend a night amidst the diverse ecosystems of Tarangire National Park, where the majestic baobab trees and a vibrant array of wildlife, from towering elephants to elusive big cats, create an unforgettable safari experience.\n\nNext, explore the Ngorongoro Crater, a UNESCO World Heritage Site celebrated for its remarkable geological features. Descend into the lush, ancient caldera, where a thriving ecosystem hosts a stunning variety of wildlife in a setting of unparalleled beauty. With our expert guides leading you, each moment of your journey will be filled with discovery and insight into Tanzania’s rich biodiversity and cultural heritage. Return to Arusha with a heart full of cherished memories from a truly unforgettable exploration of East Africa’s heartland.","image":"/assets/tour-1.webp","mapImage":"https://mambeusafaris.com/wp-content/uploads/2024/03/rafiki4days.webp","duration":"2 Days","airport":"Kilimanjaro Int. Airport","category":"Classic Safari","pricingTiers":[{"people":"1 person","price":1403},{"people":"2 people","price":855},{"people":"3 people","price":680},{"people":"4 people","price":632},{"people":"5 people","price":580},{"people":"6 people","price":557}],"itinerary":[{"day":1,"title":"Arusha – Tarangire National Park","description":"Pick up at 8:30 AM from your hotel in Arusha and depart for Tarangire National Park with a picnic lunch for a full day game drive. Tanzania’s third largest National park is known for its majestic baobab trees that dot the landscape, dwarfing the animals that feed beneath them. The Tarangire River is the centerpiece of this park which is famous for some of the largest herds of elephants in Africa. Here you may see lion, leopard, cheetah, lesser kudu, buffalo, Oryx, eland, giraffe and zebra. Post the game drive, you will head back to your camp/lodge where a delicious dinner awaits you.","image":"","accommodation":"","meals":""},{"day":2,"title":"Ngorongoro Crater Tour (5 Hours) to Arusha","description":"On the last day of your safari, you will have an early start. Finishing up with a quick breakfast you will make an early descent at around 6:30 AM into the crater floor. The Ngorongoro Crater is the world’s largest inactive, intact and unfilled volcanic caldera. It has a massive floor of about 260 sq kms with a depth of over 2000 feet. The 5-hour game drive on the crater floor will show you a lot of animal action. Keeping the camera ready is definitely recommended. The African elephant, buffalo, Black rhino, Hippos, Hyenas, Cheetahs and Lions are found in plenty. Post the picnic lunch at the beautiful Hippo pool, you will begin a steep ascend to the top exit of the crater. This is the last leg of your safari, with a 4hr drive left to Arusha. You will be dropped off to your preferred location in Arusha by 6:00 PM in the evening. With an incredible experience and loads of memories to cherish, this is the time you bid goodbye to your team.","image":"","accommodation":"","meals":"Half Board"}],"highlights":[],"included":["Airport pickup and drop off","Transportation in a 4×4 safari vehicle","Professional, English-speaking guide","Overnight accommodation according to the itinerary","Meals while on safari","Mineral water","All government taxes","All mentioned activities","All national park fees","Flying Doctors insurance (AMREF) during the safari for emergence evacuations"],"excluded":["International or Local Flights","Optional activities","Alcoholic and soft drinks","Visa fees","Tips","Personal spending money for souvenirs etc.","Travel insurance"],"gallery":[],"featured":false,"createdAt":"2025-12-23T05:39:42.069Z","updatedAt":"2026-07-15T14:26:51.784Z","path":"journey-1","style":"Comfort","days":2}];
const tours=globalThis.MAMBEU_TOURS;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>'$'+Number(v).toLocaleString('en-US');
const href=(r)=>{const [path,query]=r.split('?');return '/'+(path?path+'/':'')+(query?'?'+query:'')};
const A=(r,text,cls='')=>`<a class="${cls}" href="${href(r)}">${text}</a>`;
const img=(src,alt,cls='',priority=false)=>`<img class="${cls}" src="/assets/${src}" alt="${esc(alt)}" ${priority?'fetchpriority="high"':'loading="lazy"'} decoding="async">`;
const places=[
{slug:'serengeti',name:'Serengeti',tag:'The plains go on. The moments stay.',photo:'hero.webp',text:'Open grasslands, rocky kopjes and the wildlife-rich Seronera region form the backdrop to Mambeu’s classic, migration and calving-season journeys.',q:'Serengeti',facts:['Great Migration','Big cat country','Classic game drives']},
{slug:'ngorongoro',name:'Ngorongoro',tag:'A whole world inside a crater.',photo:'tour-298.webp',text:'Descend from the highlands into a remarkable landscape of grasslands, lakes and wildlife. Ngorongoro is a memorable part of Mambeu’s northern Tanzania itineraries.',q:'Ngorongoro',facts:['Crater game drives','Highland scenery','Northern circuit']},
{slug:'tarangire',name:'Tarangire',tag:'Elephants. Baobabs. Room to roam.',photo:'tour-295.webp',text:'Discover landscapes shaped by ancient baobabs and the Tarangire River. Mambeu’s short safaris and longer journeys include time among the park’s elephants, birds and varied wildlife.',q:'Tarangire',facts:['Elephant herds','Ancient baobabs','Birdwatching']},
{slug:'lake-manyara',name:'Lake Manyara',tag:'Forest meets the Rift Valley.',photo:'tour-293.webp',text:'Explore forest, lakeshore habitats and the Rift Valley escarpment. Lake Manyara features in several Mambeu itineraries alongside Tarangire and Ngorongoro.',q:'Manyara',facts:['Lakeside birding','Forest game drives','Rift Valley scenery']},
{slug:'ndutu',name:'Ndutu',tag:'Life begins on the southern plains.',photo:'tour-291.webp',text:'Mambeu’s calving-season safaris focus on the southern Serengeti ecosystem, with mobile camps and routes planned around seasonal wildlife movements.',q:'Calving',facts:['Calving-season journeys','Mobile tented camps','Seasonal wildlife']},
{slug:'lake-natron',name:'Lake Natron',tag:'A quieter, wilder Tanzania.',photo:'natron.webp',text:'Discover Lake Natron’s striking landscape, flamingo habitat and Maasai cultural connections. Ask Mambeu about combining a visit with a guided expedition to Ol Doinyo Lengai.',q:'Natron',facts:['Rift Valley landscapes','Community experiences','Ol Doinyo Lengai']}
];
const levels={Midrange:{number:'01',title:'More adventure.<br>Less compromise.',sub:'Spend thoughtfully. Experience fully.',image:'tour-298.webp',alt:'A place to relax between game drives',body:'Welcoming lodges and practical tented camps keep the focus on Tanzania’s wildlife. We’ll help choose stays that balance your budget, location and everyday comfort.',bullets:['A route tailored to your budget','Simple, welcoming lodge and camp options','Local guiding and personal planning'],note:'Prefer camping? Explore our separate camping collection.',cta:'Plan my midrange safari'},Comfort:{number:'02',title:'Wild days.<br>Restful nights.',sub:'Our favourite balance.',image:'tour-1.webp',alt:'A relaxed camp setting on safari',body:'Handpicked lodges and tented camps, warm hospitality and time to enjoy each place. Comfort safaris balance a rewarding route with welcoming stays.',bullets:['Thoughtful accommodation choices','Your interests, dates and pace','Optional experiences chosen around you'],note:'Our current itineraries feature stays such as Bougainvillea Safari Lodge and Serengeti Kati Kati Tented Camp. The team confirms accommodation for your dates.',cta:'Plan my comfort safari'},Luxury:{number:'03',title:'Extraordinary places.<br>Exceptional stays.',sub:'A little more of what you love.',image:'romantic.webp',alt:'A candlelit dinner setting in the bush',body:'Premium lodges and camps, with optional flights and special experiences for a more indulgent journey. Build the details around your wishes.',bullets:['Premium lodge and camp options','Optional flights and special experiences','A bespoke journey with personal attention'],note:'Luxury itineraries in the collection feature stays such as Kubu Kubu Tented Lodge and Gran Meliá Arusha. Availability is confirmed with your quotation.',cta:'Plan my luxury safari'}};
function nav(){return `<a href="#main" class="skip">Skip to content</a><header class="site-header"><div class="nav-shell"><a href="/" class="brand" aria-label="Mambeu Safaris home">${img('logo.webp','Mambeu Tanzania Safaris','',true)}</a><button class="menu-toggle" aria-expanded="false" aria-controls="main-nav">Menu</button><nav id="main-nav" aria-label="Main navigation"><div class="nav-group"><button class="nav-toggle" aria-expanded="false" aria-controls="safari-menu">Our safaris <span aria-hidden="true">⌄</span></button><div id="safari-menu" class="nav-panel" hidden>${A('safaris','All safari journeys')}${A('safaris?style=Comfort','Comfort safaris')}${A('safaris?style=Midrange','Midrange safaris')}${A('safaris?style=Luxury','Luxury safaris')}${A('safaris?style=Camping','Camping adventures')}${A('comfort','Compare comfort levels')}</div></div>${A('destinations','Destinations')}${A('experiences','Experiences')}${A('about','Our story')}<a class="nav-plan" href="/plan/">Plan my safari</a></nav></div></header>`}
function footer(){return `<section class="final-invite"><div class="wrap"><div><span class="eyebrow">TELL US WHAT YOU’RE DREAMING OF</span><h2>Your next chapter<br>starts in Tanzania.</h2></div><div><p>A few ideas are all we need. Let’s shape a journey that feels like you.</p>${A('plan','Let’s plan your safari','button light')}</div></div></section><footer><div class="wrap foot-grid"><div class="foot-intro"><a class="wordmark" href="/">MAMBEU<span>TANZANIA SAFARIS</span></a><p>Local roots. Personal journeys.<br>Wildlife, mountains and coast, thoughtfully brought together.</p><a href="https://wa.me/255796086799" target="_blank" rel="noopener" class="text-link">Talk to us on WhatsApp</a></div><div><h3>Your Tanzania</h3>${A('safaris','Safari collection')}${A('comfort','Comfort levels')}${A('kilimanjaro','Kilimanjaro')}${A('zanzibar','Zanzibar')}${A('destinations','Destinations')}</div><div><h3>Get to know us</h3>${A('about','Our story')}${A('experiences','Experiences')}${A('travel-guide','Planning & FAQs')}${A('plan','Plan your safari')}<a href="https://mambeusafaris.com/terms-conditions/" target="_blank" rel="noopener">Booking terms</a></div><div><h3>Your local team</h3><a href="mailto:info@mambeusafaris.com">info@mambeusafaris.com</a><a href="tel:+255796086799">+255 796 086 799</a><p>Arusha, Tanzania<br>Office hours 08:00–19:30</p></div></div><div class="wrap foot-base"><span>© ${new Date().getFullYear()} Mambeu Safaris</span><span>Dream · Discover · Explore</span></div></footer>`}
function itineraryRoute(t){let list=t.itinerary.map(d=>d.title.replace(/\s*[–—-]\s*.*$/,'').replace(/National Park|NP/g,'').trim()).filter(Boolean);return [...new Set(list)].slice(0,3).join(' / ')||t.highlights.slice(0,3).join(' / ')||'Northern Tanzania'}
function card(t){const available=t.pricingTiers.length>0;return `<article class="journey-card"><a class="journey-photo" href="/${t.path}/">${img(t.image.split('/').pop(),t.title)}<span class="photo-tag">${t.style}</span><span class="photo-days">${t.days} days</span></a><div class="journey-info"><p class="journey-route">${esc(itineraryRoute(t))}</p><h3>${A(t.path,esc(t.title))}</h3><p class="journey-desc">${esc(t.description.replace(/\.\.\.$/,'').slice(0,145))}${t.description.length>145?'…':''}</p><div class="journey-bottom"><span>${available?'Price by group size':'Tailored quotation'}<small>${available?'View published pricing':'Choose your dates & stays'}</small></span>${A(t.path,'View journey','text-link')}</div></div></article>`}
function stylePanel(style='Comfort'){const s=levels[style];return `<div class="stay-photo">${img(s.image,s.alt)}<span class="image-note">${style==='Comfort'?'A little space to take it all in':style==='Luxury'?'Special experiences, by arrangement':'Time to unwind between game drives'}</span></div><div class="stay-copy"><span class="eyebrow">${s.number} / ${style.toUpperCase()} SAFARIS</span><h3>${s.title}</h3><p class="stay-sub">${s.sub}</p><p>${s.body}</p><ul class="check-list">${s.bullets.map(b=>`<li>${b}</li>`).join('')}</ul><a class="button" href="/plan/?style=${style}">${s.cta}</a><p class="fineprint">${s.note}</p></div>`}
function comfortSection(){return `<section class="comfort-section" id="comfort"><div class="wrap"><div class="section-heading"><div><span class="eyebrow">YOUR SAFARI. YOUR KIND OF STAY.</span><h2>Comfort is personal.<br>Let’s find yours.</h2></div><p>Midrange and comfort at our heart.<br>Luxury when you want a little more.</p></div><div class="style-tabs" role="tablist" aria-label="Safari comfort levels">${Object.keys(levels).map(s=>`<button role="tab" id="tab-${s}" data-style="${s}" aria-selected="${s==='Comfort'}" aria-controls="stay-panel" tabindex="${s==='Comfort'?0:-1}">${s}<span>${s==='Comfort'?'The perfect balance':s==='Midrange'?'Thoughtful value':'Elevated experiences'}</span></button>`).join('')}</div><div class="stay-panel" id="stay-panel" role="tabpanel" aria-labelledby="tab-Comfort">${stylePanel()}</div></div></section>`}
function home(){return `<main id="main"><section class="home-hero"><div class="hero-image">${img('hero.webp','Wildebeest and zebras on Tanzania’s plains','',true)}</div><div class="hero-content wrap"><span class="eyebrow">TANZANIA, YOUR WAY</span><h1>Your Tanzania.<br><span>Wildly personal.</span></h1><p>Extraordinary wildlife. Welcoming stays.<br>Thoughtfully planned around you.</p><div class="hero-actions">${A('safaris','Explore our safaris','button orange')}${A('plan','Create your journey','button ghost')}</div><div class="hero-bottom"><span>Locally owned · Arusha, Tanzania</span><span>Dream. Discover. Explore.</span></div></div><a href="#discover" class="hero-scroll">Discover Mambeu</a></section><section class="discovery wrap" id="discover"><div class="discovery-title"><span class="eyebrow">FIND YOUR STARTING POINT</span><h2>Where will<br>your story go?</h2></div><form id="finder" class="finder"><div><label for="find-style">Your comfort level</label><select id="find-style"><option value="Comfort">Comfort</option><option value="Midrange">Midrange</option><option value="Luxury">Luxury</option><option value="Camping">Camping</option><option value="">Help me decide</option></select></div><div><label for="find-duration">Time to explore</label><select id="find-duration"><option value="">Any duration</option><option value="short">2–4 days</option><option value="medium">5–6 days</option><option value="long">7+ days</option></select></div><div><label for="find-interest">What draws you here?</label><select id="find-interest"><option value="">Wildlife & landscapes</option><option>Serengeti</option><option>Ngorongoro</option><option>Migration</option><option>Zanzibar</option><option>Cultural</option></select></div><button class="button" type="submit">Find my safari</button></form></section><section class="welcome wrap"><div><span class="eyebrow">WELCOME TO MAMBEU</span><h2>Big on adventure.<br>Thoughtful about<br><span class="accent">everything else.</span></h2></div><div class="welcome-copy"><p class="lead">You don’t need the most expensive safari to have an extraordinary one.</p><p>You need the right route, a knowledgeable guide and a welcoming place to end the day. From our home in Arusha, we bring these details together in journeys made around you.</p>${A('about','Meet the people behind your journey','text-link')}<div class="welcome-points"><div><b>Local roots</b><span>Locally owned in Tanzania</span></div><div><b>Your pace</b><span>Personalised routes & stays</span></div></div></div></section><section class="curated wrap"><div class="section-heading"><div><span class="eyebrow">A FEW GOOD PLACES TO BEGIN</span><h2>Journeys with<br>something more.</h2></div><div class="collection-controls"><div class="pill-tabs" aria-label="Featured journeys"><button data-feature="Comfort" aria-pressed="true">Comfort</button><button data-feature="Luxury" aria-pressed="false">Luxury</button><button data-feature="Camping" aria-pressed="false">Camping</button></div>${A('safaris','View the full collection','text-link')}</div></div><div class="featured-grid" id="featured-journeys">${[302,298,291].map(id=>card(tours.find(t=>t.id===id))).join('')}</div></section>${comfortSection()}<section class="places-section wrap"><div class="section-heading"><div><span class="eyebrow">MEET THE PLACES THAT MAKE TANZANIA</span><h2>Six landscapes.<br>Countless possibilities.</h2></div><div class="slider-actions"><button class="round-button" id="places-prev" aria-label="Previous destinations">Back</button><button class="round-button" id="places-next" aria-label="Next destinations">Next</button></div></div><div class="places-track" id="places-track" tabindex="0" aria-label="Tanzania destinations">${places.map((p,i)=>`<a class="place-card" href="/destinations/${p.slug}/">${img(p.photo,p.name+' landscape and wildlife')}<div><span class="eyebrow">0${i+1} / TANZANIA</span><h3>${p.name}</h3><p>${p.tag}</p></div></a>`).join('')}</div><div class="section-tail"><span>Connect your favourites into one personal journey.</span>${A('destinations','Explore all destinations','text-link')}</div></section><section class="beyond wrap"><div class="section-heading"><div><span class="eyebrow">MAKE ROOM FOR A DIFFERENT KIND OF WILD</span><h2>Beyond the safari.</h2></div><p>Your adventure doesn’t have to end<br>when the game drive does.</p></div><div class="beyond-grid"><a class="beyond-card sea" href="/zanzibar/">${img('zanzibar.webp','Zanzibar coastline and Indian Ocean')}<div><span class="eyebrow">ISLAND TIME</span><h3>Wildlife to<br>white sands.</h3><p>Unwind in Zanzibar.</p></div></a><a class="beyond-card mountain" href="/kilimanjaro/">${img('mountain.webp','Kilimanjaro mountain camp')}<div><span class="eyebrow">A HIGHER PERSPECTIVE</span><h3>Take the<br>higher road.</h3><p>Your Kilimanjaro adventure.</p></div></a><a class="beyond-card culture" href="/experiences/">${img('tour-296.webp','A cultural visit with local people in Tanzania')}<div><span class="eyebrow">HUMAN CONNECTIONS</span><h3>Meet another<br>side of Tanzania.</h3><p>Culture, stories and shared moments.</p></div></a></div></section><section class="local-story"><div class="wrap story-grid"><div class="story-photo">${img('team.webp','Mambeu guests beside the branded safari vehicle')}<span>OUR HOME. YOUR ADVENTURE.</span></div><div><span class="eyebrow">THE PEOPLE MAKE THE DIFFERENCE</span><h2>Good safaris begin<br>with good people.</h2><p>Mambeu is locally owned and operated. We share Tanzania through expertly guided journeys, personal attention and a commitment to responsible travel.</p><p>From your first ideas to the route, stays and special moments, we bring local knowledge to the details that matter.</p>${A('about','Get to know Mambeu','button outline')}</div></div></section><section class="wrap home-faq"><div><span class="eyebrow">A LITTLE HELP BEFORE YOU GO</span><h2>Good questions.<br>Personal answers.</h2>${A('travel-guide','All planning questions','text-link')}</div><div class="faq-list">${faqItems().slice(0,3).map(faq).join('')}</div></section></main>`}
function pageHead(label,title,text,photo=''){return `<section class="page-intro ${photo?'with-photo':''}"><div class="wrap"><span class="eyebrow">${label}</span><h1>${title}</h1><p>${text}</p></div>${photo?img(photo,'Tanzania safari scenery','intro-image',true):''}</section>`}
function catalog(){return `<main id="main">${pageHead('THE MAMBEU COLLECTION','Find your<br><span class="accent">kind of wild.</span>','22 starting points. Endless ways to make them yours. Explore our existing journeys, then tailor your route, dates and stays.')}<section class="wrap catalogue-layout"><aside class="catalogue-filters"><h2>Shape your safari</h2><label for="search">Search journeys</label><input id="search" type="search" placeholder="Park, wildlife or experience"><label for="style">Comfort level</label><select id="style"><option value="">All styles</option><option>Midrange</option><option>Comfort</option><option>Luxury</option><option>Camping</option></select><label for="duration">Days to explore</label><select id="duration"><option value="">Any duration</option><option value="short">2–4 days</option><option value="medium">5–6 days</option><option value="long">7+ days</option></select><label for="sort">Arrange journeys</label><select id="sort"><option value="recommended">Recommended</option><option value="shortest">Shortest first</option><option value="longest">Longest first</option></select><button id="reset-filters" class="text-link">Clear filters</button><div class="filter-help"><b>Something more personal?</b><p>Let’s create a journey around your ideas.</p>${A('plan','Design my safari','button outline')}</div></aside><div><div class="catalogue-top"><p id="result-count" aria-live="polite">22 journeys to explore</p><span>Tailor-made around you</span></div><p id="midrange-note" class="notice" hidden>These routes can be adapted with midrange accommodation. The published prices apply to the original itineraries; request a tailored quotation for a different comfort level.</p><div class="catalogue-grid" id="catalogue-results">${tours.map(card).join('')}</div></div></section></main>`}
function detail(t){const tiers=t.pricingTiers;const defaultTier=tiers.findIndex(p=>p.people==='2 people');return `<main id="main"><section class="journey-hero">${img(t.image.split('/').pop(),t.title,'',true)}<div class="wrap"><a href="/safaris/" class="breadcrumb">Safari collection / ${t.style}</a><span class="eyebrow">${esc(t.duration)} · TAILOR-MADE JOURNEY</span><h1>${esc(t.title)}</h1><p>${esc(itineraryRoute(t))}</p></div></section><nav class="journey-anchor-nav" aria-label="Journey sections"><div class="wrap"><a href="#overview">Overview</a><a href="#itinerary">Day by day</a><a href="#stays">Accommodation</a><a href="#included">Inclusions</a><a href="#enquire">Your quotation</a></div></nav><section class="wrap journey-layout"><article><div id="overview" class="journey-section"><span class="eyebrow">THE JOURNEY AT A GLANCE</span><h2>Make every<br>day count.</h2><p class="lead">${esc(t.fullDescription||t.description)}</p><div class="journey-facts"><div><span>Duration</span><b>${t.days} days</b></div><div><span>Published style</span><b>${t.style}</b></div><div><span>Planning</span><b>Personalised</b></div></div>${t.highlights.length?`<div class="highlights">${t.highlights.map(x=>`<span>${esc(x)}</span>`).join('')}</div>`:''}</div><div class="journey-section" id="itinerary"><div class="section-heading"><div><span class="eyebrow">YOUR TIME IN TANZANIA</span><h2>Day by day.</h2></div>${t.itinerary.length?'<button class="text-link" id="expand-days" aria-expanded="false">Expand all days</button>':''}</div>${t.itinerary.length?t.itinerary.map((d,i)=>`<details class="day" ${i===0?'open':''}><summary><span class="day-number">${String(d.day||i+1).padStart(2,'0')}</span><span><small>DAY ${d.day||i+1}</small><b>${esc(d.title)}</b></span><span class="day-icon" aria-hidden="true"></span></summary><div class="day-body"><p>${esc(d.description).replace(/\n/g,'<br>')}</p>${d.accommodation||d.meals?`<div class="day-stay">${d.accommodation?`<p><b>Stay</b> ${esc(d.accommodation)}</p>`:''}${d.meals?`<p><b>Meals & drinks</b> ${esc(d.meals)}</p>`:''}</div>`:''}</div></details>`).join(''):'<p>Your safari specialist will provide a detailed itinerary with your personalised quotation.</p>'}</div><div class="journey-section" id="stays"><span class="eyebrow">YOUR HOME ALONG THE WAY</span><h2>Where you’ll rest.</h2><div class="stay-list">${t.itinerary.filter(d=>d.accommodation&&!/no accom|end of tour/i.test(d.accommodation)).map(d=>`<div><span>Day ${d.day}</span><b>${esc(d.accommodation)}</b></div>`).join('')||'<p>Our team will suggest accommodation for your dates and preferred comfort level.</p>'}</div><p class="fineprint">Stays are subject to availability. Your final quotation confirms accommodation and any requested changes.</p><a class="text-link" href="/plan/?journey=${encodeURIComponent(t.title)}">Ask about different accommodation</a></div><div class="journey-section inclusions" id="included"><div><span class="eyebrow">WHAT’S IN YOUR JOURNEY</span><h3>Included</h3>${t.included.length?`<ul>${t.included.filter(x=>!/^\(/.test(x)).map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:'<p>Inclusions are confirmed in your personalised quotation.</p>'}</div><div><span class="eyebrow">PLAN FOR THESE SEPARATELY</span><h3>Excluded</h3>${t.excluded.length?`<ul>${t.excluded.filter(x=>!/^\(/.test(x)).map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:'<p>Exclusions and optional activities are set out in your quotation.</p>'}</div></div><p class="fineprint">Activities and meals apply as specified in the itinerary. Optional experiences, upgrades and changes are quoted separately.</p></article><aside class="quotation" id="enquire"><span class="eyebrow">LET’S MAKE IT YOURS</span><h3>Your journey.<br>Your details.</h3>${tiers.length?`<label for="group-size">Number of travellers</label><select id="group-size">${tiers.map((p,i)=>`<option value="${i}" ${i===defaultTier?'selected':''}>${esc(p.people)}</option>`).join('')}</select><p class="quoted-price" id="journey-price">${money(tiers[Math.max(defaultTier,0)].price)}</p><span class="price-unit">per person · USD</span><p class="fineprint">Published group-size price. Your dates, availability and requested changes are confirmed in a personalised quotation.</p>`:'<p>Request a quotation based on your dates, group size and preferred accommodation.</p>'}<a class="button orange" href="/plan/?journey=${encodeURIComponent(t.title)}&style=${t.style}">Enquire about this journey</a><a class="whatsapp-link" href="https://wa.me/255796086799?text=${encodeURIComponent('Hello Mambeu, I would like to discuss '+t.title)}" target="_blank" rel="noopener">Talk to us on WhatsApp</a><div class="quotation-note"><b>Love the route, want different stays?</b><p>Ask us to tailor the journey to midrange, comfort or luxury accommodation.</p></div></aside></section><section class="wrap related"><div class="section-heading"><h2>Keep exploring.</h2>${A('safaris','All safari journeys','text-link')}</div><div class="related-grid">${tours.filter(x=>x.id!==t.id&&x.style===t.style).slice(0,3).map(card).join('')}</div></section></main>`}
function destinations(){return `<main id="main">${pageHead('PLACES THAT STAY WITH YOU','One Tanzania.<br><span class="accent">So many worlds.</span>','Legendary wildlife parks, mountain landscapes and an Indian Ocean coast. Connect your favourite places into one personal journey.')}<section class="wrap destination-grid">${places.map((p,i)=>`<a class="destination-tile" href="/destinations/${p.slug}/">${img(p.photo,p.name)}<div><span class="eyebrow">0${i+1} / EXPLORE</span><h2>${p.name}</h2><p>${p.tag}</p></div></a>`).join('')}${[['kilimanjaro','Kilimanjaro','mountain.webp','A higher perspective.'],['zanzibar','Zanzibar','zanzibar.webp','Slow down by the sea.']].map(p=>`<a class="destination-tile" href="/${p[0]}/">${img(p[2],p[1])}<div><span class="eyebrow">KEEP EXPLORING</span><h2>${p[1]}</h2><p>${p[3]}</p></div></a>`).join('')}</section></main>`}
function placePage(p){return `<main id="main">${pageHead('MEET TANZANIA',p.name,p.tag,p.photo)}<section class="wrap split-story"><div><span class="eyebrow">A PLACE TO REMEMBER</span><h2>A different view.<br>A deeper connection.</h2></div><div><p class="lead">${p.text}</p><div class="highlights">${p.facts.map(f=>`<span>${f}</span>`).join('')}</div><a class="button" href="/safaris/?q=${encodeURIComponent(p.q)}">Explore journeys here</a></div></section><section class="wrap related"><div class="section-heading"><h2>Start with a journey.</h2><a class="text-link" href="/plan/?interest=${encodeURIComponent(p.name)}">Plan a personal route</a></div><div class="related-grid">${tours.filter(t=>JSON.stringify(t).toLowerCase().includes(p.q.toLowerCase())).slice(0,3).map(card).join('')||'<div class="empty-results"><h3>A journey made for you.</h3><p>Ask our local team to include this destination in a personal itinerary.</p><a class="button" href="/plan/?interest='+encodeURIComponent(p.name)+'">Plan a journey here</a></div>'}</div></section></main>`}
function about(){return `<main id="main">${pageHead('THE PEOPLE BEHIND YOUR JOURNEY','Rooted in Tanzania.<br><span class="accent">Made around you.</span>','Mambeu Safaris is locally owned and based in Arusha, sharing the country we call home through personal wildlife, mountain, cultural and beach journeys.')}<section class="wrap story-grid about-story"><div class="story-photo">${img('team.webp','Mambeu guests and safari vehicle in Tanzania')}<span>LOCAL ROOTS. PERSONAL JOURNEYS.</span></div><div><span class="eyebrow">WHO WE ARE</span><h2>Local knowledge.<br>Human connections.</h2><p>Founded by local Tanzanians, Mambeu brings a close connection to Tanzania’s landscapes, wildlife and communities. Our team plans bespoke journeys through the places we know and love.</p><p>We welcome different budgets and travel styles. We help choose routes, stays and activities around your comfort, interests and time available.</p><p>Responsible tourism is part of our approach: respecting wildlife, supporting local communities and making meaningful connections with the places you visit.</p></div></section><section class="values"><div class="wrap"><span class="eyebrow">WHAT GUIDES US</span><h2>A journey with care<br>at its heart.</h2><div class="values-grid">${[['01','Personal by design','Your dates, interests and comfort level shape the journey. We listen first, then help you connect the details.'],['02','Rooted in Tanzania','Local knowledge helps us choose routes, stays and experiences that work together.'],['03','Travel responsibly','Respect for nature and communities guides how we share Tanzania with our visitors.']].map(v=>`<article><span>${v[0]}</span><h3>${v[1]}</h3><p>${v[2]}</p></article>`).join('')}</div></div></section><section class="wrap split-story"><div><span class="eyebrow">OUR MISSION</span><h2>Help every traveller<br>find their Tanzania.</h2></div><div><p class="lead">We create personalised travel experiences that showcase Tanzania’s natural beauty and cultural richness, with comfort, safety and local insight.</p><p>Our vision is to grow through thoughtful service and responsible tourism, supporting local communities while sharing the country’s extraordinary places.</p>${A('plan','Meet your safari specialist','button')}</div></section></main>`}
function comfort(){return `<main id="main">${pageHead('YOUR KIND OF STAY','Adventure outside.<br><span class="accent">Comfort within.</span>','Midrange and comfort are at the heart of our approach. Luxury and camping remain part of the possibilities. Choose how you want your journey to feel.')}${comfortSection()}<section class="wrap split-story"><div><span class="eyebrow">A THOUGHTFUL BALANCE</span><h2>Spend on the things<br>you’ll remember.</h2></div><div><p class="lead">Your budget influences accommodation, length of stay and optional experiences. We’ll help you decide where extra comfort makes a difference.</p><p>The published journeys are starting points. When you enquire, we’ll suggest specific lodges and tented camps for your dates and confirm what is included before you book.</p>${A('safaris?style=Camping','Explore our camping journeys','text-link')}</div></section></main>`}
function thematic(type){const mountain=type==='kilimanjaro';const blocks=mountain?[['Prepare well','Share your hiking experience, fitness and questions with our team.'],['Choose your route','Discuss route options, duration, equipment and preparation before confirming your climb.'],['Keep exploring','Add a wildlife safari or a Zanzibar stay to round off your adventure.']]:[['Time by the sea','Unhurried days, warm waters and accommodation matched to your comfort level.'],['Culture & history','Explore Stone Town, local flavours and the island’s spice heritage.'],['Ocean experiences','Ask about snorkelling, diving and excursions for your travel dates.']];return `<main id="main">${pageHead(mountain?'MOUNTAIN ADVENTURES':'SAFARI & ISLAND ESCAPES',mountain?'Take the<br>higher road.':'From wild plains<br>to white sands.',mountain?'A Kilimanjaro adventure with personal preparation, local guiding and support along the way.':'Pair your wildlife adventure with Zanzibar’s beaches, historic Stone Town and the Indian Ocean.',mountain?'mountain.webp':'zanzibar.webp')}<section class="wrap split-story"><div><span class="eyebrow">${mountain?'THE JOURNEY IS THE STORY':'MAKE TIME TO SLOW DOWN'}</span><h2>${mountain?'More than<br>a summit.':'Your island.<br>Your pace.'}</h2></div><div><p class="lead">${mountain?'Mambeu’s mountain experiences bring expert guiding, equipment and preparation together with a personal approach.':'Build a Zanzibar stay around your interests, from beach relaxation to cultural exploration and time on the water.'}</p><p>${mountain?'Tell us about your hiking background, preferred dates and available time. We’ll discuss suitable routes, support and preparation before providing your quotation.':'Accommodation, flights, airport transfers and excursions can be discussed together so your safari and island stay connect smoothly.'}</p><a class="button orange" href="/plan/?interest=${mountain?'Kilimanjaro':'Zanzibar'}">Plan my ${mountain?'mountain adventure':'island escape'}</a></div></section><section class="values"><div class="wrap values-grid">${blocks.map((b,i)=>`<article><span>0${i+1}</span><h3>${b[0]}</h3><p>${b[1]}</p></article>`).join('')}</div></section>${mountain?'':`<section class="wrap related"><div class="section-heading"><h2>Safari from Zanzibar.</h2>${A('safaris?q=Zanzibar','Explore these journeys','text-link')}</div><div class="related-grid">${tours.filter(t=>t.title.includes('Zanzibar')).map(card).join('')}</div></section>`}</main>`}
function experiences(){const experiences=[['Family safaris','Time together, thoughtfully planned.','family.webp','A route and pace shaped around your family, with accommodation and activities discussed around everyone’s needs.','Family'],['Romantic journeys','Moments made for two.','romantic.webp','Personal escapes with thoughtful stays and optional special experiences, from the bush to Zanzibar.','Romantic'],['Hot-air balloon safari','See the plains differently.','balloon.webp','Ask about a balloon flight as an optional addition to your Serengeti safari. Availability and costs are confirmed separately.','Balloon'],['Cultural connections','People, stories and traditions.','tour-296.webp','Explore Maasai and Hadzabe experiences with respectful, locally guided visits.','Cultural experiences']];return `<main id="main">${pageHead('FOLLOW YOUR CURIOSITY','A safari is only<br><span class="accent">the beginning.</span>','Add experiences that mean something to you, from cultural connections to a different view of the plains.')}<section class="wrap experience-list">${experiences.map((x,i)=>`<article class="experience-row"><div>${img(x[2],x[0])}</div><div><span class="eyebrow">0${i+1} / ${x[0].toUpperCase()}</span><h2>${x[1]}</h2><p>${x[3]}</p><a class="button outline" href="/plan/?interest=${encodeURIComponent(x[4])}">Include this in my journey</a></div></article>`).join('')}</section></main>`}
function faqItems(){return [['Can I change a published itinerary?','Yes. The journeys are starting points. We can discuss changes to your route, nights, accommodation and activities before preparing a personal quotation.'],['What is the difference between midrange and comfort?','Midrange focuses on practical, welcoming stays and thoughtful value. Comfort offers a balance of location, hospitality and restful accommodation. The actual lodges and camps are confirmed for your dates in your quotation.'],['Can I combine safari with Zanzibar?','Yes. Share how long you want on safari and at the beach. We can discuss stays, flights, transfers and excursions as part of your itinerary.'],['What determines my safari price?','Travel dates, group size, length of stay, accommodation and optional activities all influence your quotation. Published prices apply to the existing itinerary; changes are quoted by the team.'],['What should I pack?','Comfortable clothing, suitable footwear, sun protection and your personal essentials are a useful start. Ask the team for a packing list suited to your safari or mountain itinerary.'],['Where do I check entry and travel requirements?','Verify current passport, visa, health and insurance requirements with the relevant official authorities before travelling. Our team can help point you towards the information you need.'],['How do I book?','Send your ideas through our planner, WhatsApp or email. We’ll discuss the details, provide a quotation and share applicable booking terms before confirmation.']]}
function faq(x){return `<details class="faq"><summary>${x[0]}<span aria-hidden="true"></span></summary><p>${x[1]}</p></details>`}
function guide(){return `<main id="main">${pageHead('A LITTLE PLANNING GOES A LONG WAY','Good questions.<br><span class="accent">Clear answers.</span>','Practical starting points for your safari, mountain journey or Zanzibar escape.')}<section class="wrap faq-page"><aside><span class="eyebrow">YOUR LOCAL TEAM</span><h2>Still curious?</h2><p>Let’s talk through your plans.</p>${A('plan','Ask a safari specialist','button')}</aside><div class="faq-list">${faqItems().map(faq).join('')}</div></section></main>`}
function plan(){return `<main id="main">${pageHead('LET’S MAKE IT YOURS','Your ideas.<br><span class="accent">Our Tanzania.</span>','Tell us what you have in mind. We’ll help shape a journey around your interests, dates and comfort level.')}<section class="wrap planner-layout"><aside><span class="eyebrow">TALK TO YOUR LOCAL TEAM</span><h2>No perfect plan<br>needed.</h2><p>Share what you know. We’ll help with the rest.</p><ol class="plan-steps"><li><b>Share your ideas</b><span>Your dates, interests and comfort.</span></li><li><b>Shape the journey</b><span>A personal route and quotation.</span></li><li><b>Make it happen</b><span>Confirm the details with our team.</span></li></ol><div class="planner-contact"><a href="mailto:info@mambeusafaris.com">info@mambeusafaris.com</a><a href="tel:+255796086799">+255 796 086 799</a><span>Arusha, Tanzania</span></div></aside><form id="plan-form" class="planner-form" action="mailto:info@mambeusafaris.com" method="post" enctype="text/plain"><span class="eyebrow">YOUR JOURNEY STARTS HERE</span><div class="form-grid"><div class="field"><label for="name">Your name *</label><input id="name" name="name" autocomplete="name" required maxlength="120"></div><div class="field"><label for="email">Email address *</label><input id="email" name="email" type="email" autocomplete="email" required maxlength="200"></div><div class="field"><label for="phone">Phone / WhatsApp</label><input id="phone" name="phone" type="tel" autocomplete="tel" maxlength="50"></div><div class="field"><label for="country">Country of residence</label><input id="country" name="country" autocomplete="country-name" maxlength="100"></div><div class="field"><label for="date">Preferred arrival date</label><input id="date" name="date" type="date"></div><div class="field"><label for="guests">Number of travellers *</label><input id="guests" name="guests" type="number" min="1" max="100" required value="2"></div><div class="field"><label for="days">Time available</label><select id="days" name="days"><option>Not sure yet</option><option>2–4 days</option><option>5–6 days</option><option>7–9 days</option><option>10+ days</option></select></div><div class="field"><label for="plan-style">Preferred comfort level</label><select id="plan-style" name="style"><option>Comfort</option><option>Midrange</option><option>Luxury</option><option>Camping</option><option>Please advise me</option></select></div><div class="field"><label for="interest">Main interest</label><select id="interest" name="interest"><option>Wildlife safari</option><option>Safari and beach</option><option>Kilimanjaro</option><option>Zanzibar</option><option>Family</option><option>Romantic</option><option>Balloon</option><option>Cultural experiences</option></select></div><div class="field"><label for="budget">Safari budget per person (USD)</label><input id="budget" name="budget" placeholder="e.g. 2,500, excluding flights" maxlength="100"></div><div class="field full"><label for="journey">A journey you like (optional)</label><input id="journey" name="journey" maxlength="200"></div><div class="field full"><label for="message">Tell us a little more</label><textarea id="message" name="message" rows="4" maxlength="3000" placeholder="Favourite parks, children’s ages, special occasions or anything we should know"></textarea></div></div><div class="form-actions"><button class="button orange" type="submit" name="channel" value="whatsapp">Prepare WhatsApp enquiry</button><button class="button outline" type="submit" name="channel" value="email">Prepare email enquiry</button></div><p class="fineprint">Review your enquiry below, then send it through WhatsApp or your email app. Nothing is sent until you do.</p><div id="enquiry-preview" class="enquiry-preview" hidden aria-live="polite"><h3>Your enquiry is ready.</h3><p>Review the details, then choose how to send your message to Mambeu.</p><pre id="enquiry-text"></pre><div class="form-actions"><a id="send-whatsapp" class="button" target="_blank" rel="noopener">Open WhatsApp</a><a id="send-email" class="button outline">Open email</a><button class="text-link" type="button" id="copy-enquiry">Copy enquiry</button></div><p id="copy-status" role="status"></p></div></form></section></main>`}
function renderPage(route=''){let page,title='Tanzania, Your Way';let t=tours.find(t=>t.path===route);if(t){page=detail(t);title=t.title}else if(!route){page=home()}else if(route==='safaris'){page=catalog();title='Safari Collection'}else if(route==='about'){page=about();title='Our Story'}else if(route==='comfort'){page=comfort();title='Your Comfort Level'}else if(route==='destinations'){page=destinations();title='Tanzania Destinations'}else if(route.startsWith('destinations/')){let p=places.find(p=>route==='destinations/'+p.slug);page=p?placePage(p):destinations();title=p?.name||'Destinations'}else if(['kilimanjaro','zanzibar'].includes(route)){page=thematic(route);title=route==='kilimanjaro'?'Kilimanjaro Adventures':'Zanzibar Escapes'}else if(route==='experiences'){page=experiences();title='Safari Experiences'}else if(route==='travel-guide'){page=guide();title='Planning & FAQs'}else if(route==='plan'){page=plan();title='Plan Your Journey'}else{page='<main id="main">'+pageHead('A DIFFERENT TRAIL','Let’s find your way.','This page isn’t here. Explore our safari collection or talk with the team.')+'<section class="wrap">'+A('safaris','Explore our safaris','button')+'</section></main>';title='Page Not Found'}return {html:nav()+page+footer(),title:title+' | Mambeu Safaris',description:t?(t.fullDescription||t.description).slice(0,170):'Personal Tanzania journeys with Mambeu Safaris. Explore midrange and comfort safaris, luxury stays, Kilimanjaro and Zanzibar with our local Arusha team.'}}
globalThis.mambeuRender=renderPage;
function bind(){const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];const route=location.pathname.replace(/^\/+|\/+$/g,'');const params=new URLSearchParams(location.search);const nav=$('#main-nav'),menu=$('.menu-toggle');const closeMenus=()=>{$$('.nav-toggle').forEach(b=>{b.setAttribute('aria-expanded','false');$('#'+b.getAttribute('aria-controls')).hidden=true})};menu.addEventListener('click',()=>{let open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));nav.classList.toggle('is-open',open);if(!open)closeMenus()});$$('.nav-toggle').forEach(b=>b.addEventListener('click',()=>{const open=b.getAttribute('aria-expanded')!=='true';closeMenus();b.setAttribute('aria-expanded',String(open));$('#'+b.getAttribute('aria-controls')).hidden=!open}));document.addEventListener('click',e=>{if(!e.target.closest('.nav-group'))closeMenus()});document.addEventListener('keydown',e=>{if(e.key==='Escape'){const active=document.activeElement;const group=active?.closest('.nav-group');closeMenus();if(group)group.querySelector('button').focus();if(nav.classList.contains('is-open')){nav.classList.remove('is-open');menu.setAttribute('aria-expanded','false');menu.focus()}}});$$('nav a').forEach(a=>{if(a.getAttribute('href').split('?')[0]===location.pathname)a.setAttribute('aria-current','page')});
if($('#finder'))$('#finder').addEventListener('submit',e=>{e.preventDefault();location.assign('/safaris/?'+new URLSearchParams({style:$('#find-style').value,duration:$('#find-duration').value,q:$('#find-interest').value}))});
$$('[data-feature]').forEach(b=>b.addEventListener('click',()=>{let s=b.dataset.feature;$$('[data-feature]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));let list=s==='Comfort'?[302,298,291].map(id=>tours.find(t=>t.id===id)):tours.filter(t=>t.style===s).slice(0,3);$('#featured-journeys').innerHTML=list.map(card).join('')}));
function switchStyle(b){$$('[data-style]').forEach(x=>{x.setAttribute('aria-selected',String(x===b));x.tabIndex=x===b?0:-1});$('#stay-panel').innerHTML=stylePanel(b.dataset.style);$('#stay-panel').setAttribute('aria-labelledby',b.id)}
$$('[data-style]').forEach((b,i)=>{b.addEventListener('click',()=>switchStyle(b));b.addEventListener('keydown',e=>{const list=$$('[data-style]');let n;if(e.key==='ArrowRight')n=(i+1)%list.length;else if(e.key==='ArrowLeft')n=(i+list.length-1)%list.length;else if(e.key==='Home')n=0;else if(e.key==='End')n=list.length-1;if(n!==undefined){e.preventDefault();switchStyle(list[n]);list[n].focus()}})});
if($('#places-track')){const track=$('#places-track');const update=()=>{$('#places-prev').disabled=track.scrollLeft<=2;$('#places-next').disabled=track.scrollLeft>=track.scrollWidth-track.clientWidth-2};$('#places-prev').onclick=()=>track.scrollBy({left:-(track.clientWidth*.8),behavior:'smooth'});$('#places-next').onclick=()=>track.scrollBy({left:track.clientWidth*.8,behavior:'smooth'});track.addEventListener('scroll',update);window.addEventListener('resize',update);update()}
if(route==='safaris'){const search=$('#search'),style=$('#style'),duration=$('#duration'),sort=$('#sort');search.value=params.get('q')||'';style.value=params.get('style')||'';duration.value=params.get('duration')||'';const filter=()=>{const q=search.value.trim().toLowerCase(),s=style.value,d=duration.value;let result=tours.filter(t=>(!s||t.style===s||(s==='Midrange'&&t.style==='Comfort'))&&(!d||(d==='short'&&t.days<=4)||(d==='medium'&&t.days>=5&&t.days<=6)||(d==='long'&&t.days>=7))&&(!q||JSON.stringify([t.title,t.fullDescription,t.highlights,t.itinerary]).toLowerCase().includes(q)));if(sort.value==='shortest')result.sort((a,b)=>a.days-b.days);if(sort.value==='longest')result.sort((a,b)=>b.days-a.days);$('#result-count').textContent=`${result.length} ${result.length===1?'journey':'journeys'} to explore`;$('#midrange-note').hidden=s!=='Midrange';$('#catalogue-results').innerHTML=result.length?result.map(card).join(''):'<div class="empty-results"><h3>A different starting point?</h3><p>No journeys match these choices. Clear the filters or ask us for a personal itinerary.</p><button class="button outline" id="empty-reset">Clear filters</button><a class="text-link" href="/plan/">Design my safari</a></div>';if($('#empty-reset'))$('#empty-reset').onclick=reset;const query=new URLSearchParams();if(q)query.set('q',search.value);if(s)query.set('style',s);if(d)query.set('duration',d);history.replaceState(null,'','/safaris/'+(query.size?'?'+query:''))};const reset=()=>{search.value='';style.value='';duration.value='';sort.value='recommended';filter()};[search,style,duration,sort].forEach(x=>x.addEventListener('input',filter));$('#reset-filters').onclick=reset;filter()}
if(route.startsWith('journey-')){const t=tours.find(t=>t.path===route);if(t&&$('#group-size'))$('#group-size').onchange=()=>{$('#journey-price').textContent=money(t.pricingTiers[Number($('#group-size').value)].price)};if($('#expand-days'))$('#expand-days').onclick=()=>{const b=$('#expand-days'),open=b.getAttribute('aria-expanded')!=='true';$$('.day').forEach(d=>d.open=open);b.setAttribute('aria-expanded',String(open));b.textContent=open?'Collapse all days':'Expand all days'}}
if(route==='plan'){['style','journey'].forEach(key=>{let el=key==='style'?$('#plan-style'):$('#journey');if(params.has(key)){if(el.tagName==='SELECT'&&![...el.options].some(o=>o.value===params.get(key)))return;el.value=params.get(key)}});if(params.has('interest')){const v=params.get('interest');if([...$('#interest').options].some(o=>o.value===v))$('#interest').value=v;else $('#message').value='I would like to include '+v+' in my journey.'}let today=new Date();$('#date').min=today.toLocaleDateString('en-CA',{timeZone:'Africa/Dar_es_Salaam'});$('#plan-form').addEventListener('submit',e=>{e.preventDefault();if(!e.target.reportValidity())return;const values=Object.fromEntries(new FormData(e.target));const msg='Hello Mambeu Safaris, I would like to plan a journey.\n\n'+Object.entries(values).filter(([,v])=>String(v).trim()).map(([k,v])=>k.charAt(0).toUpperCase()+k.slice(1)+': '+String(v).trim()).join('\n');$('#enquiry-text').textContent=msg;$('#send-whatsapp').href='https://wa.me/255796086799?text='+encodeURIComponent(msg);$('#send-email').href='mailto:info@mambeusafaris.com?subject='+encodeURIComponent('Safari enquiry from '+values.name)+'&body='+encodeURIComponent(msg);$('#enquiry-preview').hidden=false;$('#copy-status').textContent='';const channel=e.submitter?.value||'whatsapp';const target=$('#send-'+channel);target.focus();$('#enquiry-preview').scrollIntoView({behavior:'smooth',block:'nearest'})});$('#copy-enquiry').onclick=async()=>{try{if(!navigator.clipboard?.writeText)throw new Error();await navigator.clipboard.writeText($('#enquiry-text').textContent);$('#copy-status').textContent='Enquiry copied.'}catch{const selection=window.getSelection(),range=document.createRange();range.selectNodeContents($('#enquiry-text'));selection.removeAllRanges();selection.addRange(range);$('#copy-status').textContent='Message selected. Copy it using your device’s copy command.'}}}
}
